insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('wiatschoftskaumma', 'Wiatschoftskaumma', '', '', '', '', 'Wirtschaftskammer', '[{"kategorie": "", "text": "Sie umfasst alle gewerblichen Unternehmen des Landes und ist auf Bundes- und Länderebene organisiert"}, {"kategorie": "", "text": "Die Wirtschaftskammer hat den Auftrag, die wirtschaftlichen Interessen ihrer Mitglieder zu vertreten, sie zu unterstützen und zu fördern, und ist ein zentraler Akteur der österreichischen [[Sozialpartnerschaft]]"}, {"kategorie": "", "text": "Aufgrund der Pflichtmitgliedschaft gehören alle Unternehmen in Österreich, die ein Gewerbe betreiben, automatisch der Wirtschaftskammer an und zahlen Pflichtbeiträge"}, {"kategorie": "", "text": "Die Wirtschaftskammer führt gemeinsam mit den [[Gewerkschaften]] die [[Kollektivvertragsverhandlungen]]. Diese legen unter anderem Mindestlöhne, Arbeitszeiten und andere arbeitsrechtliche Bedingungen fest. Sie spielt eine zentrale Rolle in der [[Sozialpartnerschaft]] und trägt zur Sicherung des sozialen Friedens und der wirtschaftlichen Stabilität in Österreich bei"}, {"kategorie": "", "text": "Die Wirtschaftskammer bietet eine Vielzahl an Beratungs- und Serviceleistungen für ihre Mitglieder an. Dazu gehören Rechtsberatung, Steuerberatung, Unternehmensgründungsberatung, Exportberatung und Unterstützung in Fragen zu Finanzierung, Digitalisierung und Innovation. Sie unterstützt Unternehmer auch bei der Betriebsnachfolge und Unternehmensführung"}, {"kategorie": "", "text": "Die Wirtschaftskammer engagiert sich stark im Bereich der Aus- und Weiterbildung. Sie ist verantwortlich für die Lehrlingsausbildung und fördert die berufliche Qualifikation durch Bildungseinrichtungen wie die [[WIFI]] (Wirtschaftsförderungsinstitut), das vielfältige Weiterbildungsmöglichkeiten und Kurse anbietet"}, {"kategorie": "", "text": "Die Wirtschaftskammer fördert österreichische Unternehmen, indem sie Informationen und Unterstützung für den Markteintritt im Ausland bietet. Sie betreibt weltweit Außenwirtschaftscenter, die österreichischen Firmen bei der Internationalisierung helfen, und organisiert internationale Messen und Wirtschaftsdelegationen"}, {"kategorie": "", "text": "Die Wirtschaftskammer Österreich ist föderal organisiert und besteht aus einer Bundesorganisation, den neun Wirtschaftskammern der Bundesländer sowie Fachorganisationen für verschiedene Branchen (z. B. Handel, Tourismus, Industrie). Diese Struktur ermöglicht eine effektive Interessenvertretung auf Bundes- und Landesebene sowie eine zielgerichtete Unterstützung für spezifische Branchenbedürfnisse"}, {"kategorie": "", "text": "Die WKÖ wird vom Wirtschaftsparlament und einem Präsidenten geführt. Das Wirtschaftsparlament setzt sich aus Vertretern der Mitgliedsbetriebe zusammen und entscheidet über grundlegende wirtschaftspolitische Positionen."}]'::jsonb, ''),
  ('laundwiatschoftskaumma', 'Laundwiatschoftskaumma', '', '', '', '', 'Landwirtschaftskammer', '[{"kategorie": "allg.", "text": "\"gesetzliche [[Interessenvertretung]] der Land- und Forstwirte in Österreich\""}, {"kategorie": "", "text": "Sie setzt sich für die wirtschaftlichen, sozialen und rechtlichen Interessen der Bauern und landwirtschaftlichen Betriebe ein und bietet ihren Mitgliedern Beratung, Unterstützung und Weiterbildungsangebote"}, {"kategorie": "", "text": "Die Landwirtschaftskammer ist auf Bundes- und Landesebene organisiert und vertritt sowohl individuelle Landwirte als auch deren Organisationen und Betriebe"}, {"kategorie": "", "text": "Sie setzt sich für günstige agrarpolitische Rahmenbedingungen und Maßnahmen zur Förderung der Landwirtschaft ein"}, {"kategorie": "", "text": "Die Landwirtschaftskammer unterstützt Landwirte auch bei Anträgen auf Fördermittel und EU-Zahlungen und gibt Hilfestellungen zu modernen Anbau- und Produktionsmethoden. Sie fördert den Einsatz innovativer Technologien und unterstützt die Bauern dabei, sich an neue Marktentwicklungen und Umweltauflagen anzupassen"}, {"kategorie": "", "text": "In Krisensituationen, wie etwa Naturkatastrophen, Ernteausfällen oder Marktkrisen, leistet die Landwirtschaftskammer Unterstützung und setzt sich für finanzielle Hilfsmaßnahmen für betroffene Landwirte ein"}, {"kategorie": "", "text": "Die Landwirtschaftskammer spielt eine aktive Rolle in der [[Sozialpartnerschaft]] und verhandelt mit anderen Interessenvertretungen, um Arbeitsbedingungen und wirtschaftliche Rahmenbedingungen in der Landwirtschaft zu gestalten"}, {"kategorie": "", "text": "Die Landwirtschaftskammer ist föderal organisiert und besteht aus neun Landes-Landwirtschaftskammern sowie einer Bundeskammer. Die Kammer wird von einem Präsidenten und einem Kammervorstand geleitet. Die Mitglieder der Landwirtschaftskammer wählen ihre Vertreter in die Kammerorgane, die über agrarpolitische Positionen und Programme entscheiden"}, {"kategorie": "", "text": "Die Landwirtschaftskammer finanziert sich durch Pflichtbeiträge der land- und forstwirtschaftlichen Betriebe, die gesetzlich zur Mitgliedschaft in der Kammer verpflichtet sind. Diese Pflichtmitgliedschaft sichert der Kammer eine breite Vertretungsbasis und ermöglicht eine stabile Finanzierung ihrer Aufgaben und Dienstleistungen."}]'::jsonb, ''),
  ('industriillenvereinigung', 'Industriillenvereinigung', '', '', '', '', 'Industriellenvereinigung', '[{"kategorie": "", "text": "Die IV setzt sich für die Stärkung der Wettbewerbsfähigkeit, Innovationsfähigkeit und Nachhaltigkeit der österreichischen Industrie ein und engagiert sich für wirtschaftspolitische Rahmenbedingungen, die die Position der Industrie auf nationaler und internationaler Ebene verbessern"}, {"kategorie": "", "text": "Die Mitglieder der IV stammen aus verschiedenen Branchen wie Maschinenbau, Chemie, Automobilindustrie, IT und Energie"}, {"kategorie": "", "text": "Die IV vertritt die Anliegen und Interessen der Industrieunternehmen gegenüber der Politik, der [[Verwaltung]] und in der Öffentlichkeit. Sie setzt sich für wirtschaftspolitische Rahmenbedingungen ein, die der Industrie Wachstum und Wettbewerbsfähigkeit ermöglichen, und fördert Innovation und Digitalisierung"}, {"kategorie": "", "text": "Die Industriellenvereinigung nimmt aktiv Einfluss auf die österreichische und europäische Wirtschaftspolitik. Sie erarbeitet Vorschläge und Positionspapiere zu wirtschaftspolitischen Themen und bringt sich in Gesetzgebungsverfahren ein, um industriepolitische Anliegen zu fördern"}, {"kategorie": "", "text": "Die IV unterstützt ihre Mitglieder bei Innovationsprojekten und der Umsetzung von Digitalisierung in der Industrie. Sie bietet Informationen zu Förderprogrammen und unterstützt den Austausch über neue Technologien und Best Practices"}, {"kategorie": "", "text": "Die Industriellenvereinigung engagiert sich stark im Bereich Bildung und Fachkräfteförderung. Sie setzt sich für eine praxisorientierte Ausbildung, Investitionen in technische Bildung und die Förderung von MINT-Fächern (Mathematik, Informatik, Naturwissenschaften und Technik) ein, um dem Fachkräftemangel in der Industrie entgegenzuwirken"}, {"kategorie": "", "text": "Die IV bietet ihren Mitgliedern Beratung und Serviceleistungen, beispielsweise zu Fragen der Standortpolitik, Unternehmensführung und Fördermöglichkeiten. Sie unterstützt Unternehmen auch bei rechtlichen und wirtschaftlichen Fragestellungen sowie bei internationalen Expansionsprojekten"}, {"kategorie": "", "text": "Die IV fördert die internationale Wettbewerbsfähigkeit ihrer Mitglieder durch Netzwerke und Kooperationen auf europäischer und globaler Ebene. Sie unterstützt Unternehmen beim Markteintritt und der Expansion im Ausland und setzt sich für einen freien und fairen Welthandel ein"}, {"kategorie": "", "text": "Die Industriellenvereinigung ist föderal organisiert und besteht aus der Bundesorganisation in Wien sowie Landesgruppen in allen neun Bundesländern. Die Bundesorganisation ist für überregionale und internationale Angelegenheiten zuständig, während die Landesgruppen regionale Interessen vertreten und spezifische regionale Themen bearbeiten"}, {"kategorie": "", "text": "Die IV wird von einem Präsidenten und einem Generalsekretär geleitet. Die Mitglieder der Industriellenvereinigung wählen ihre Vertreter und bestimmen so die strategische Ausrichtung der Organisation. Der Vorstand der IV setzt sich aus Vertretern der Mitgliedsunternehmen zusammen und entscheidet über die zentralen politischen und wirtschaftlichen Anliegen der Vereinigung"}, {"kategorie": "", "text": "Die Mitgliedschaft in der Industriellenvereinigung ist freiwillig. Die IV finanziert sich aus Mitgliedsbeiträgen der Unternehmen, die sich zu den Zielen der IV bekennen und von den Service- und Beratungsleistungen profitieren möchten. Mitglieder sind vor allem große und mittelständische Unternehmen aus der Industrie und industrienahen Sektoren."}]'::jsonb, ''),
  ('ngo', 'NGO', '', '', '', '', 'NGO', '[{"kategorie": "", "text": "In Österreich spielen NGOs eine wichtige Rolle bei der Förderung des Gemeinwohls, der Vertretung von Bürgerinteressen und der Unterstützung benachteiligter Gruppen"}, {"kategorie": "", "text": "NGOs agieren oft als Kontrollinstanzen gegenüber dem [[Staat]] und Unternehmen und tragen dazu bei, gesellschaftliche Themen zu sensibilisieren und Lösungen für soziale und ökologische Herausforderungen anzubieten"}, {"kategorie": "", "text": "NGOs in Österreich decken eine Vielzahl an Themen ab, wie Umweltschutz, Menschenrechte, Flüchtlingshilfe, Gesundheitsförderung, Armutsbekämpfung und Tierschutz. Bekannte NGOs in Österreich sind etwa Greenpeace und Global 2000 im Umweltschutz, Amnesty International und Caritas im sozialen Bereich sowie die Armutskonferenz und SOS Mitmensch im Bereich soziale Gerechtigkeit und Menschenrechte"}, {"kategorie": "", "text": "NGOs überwachen staatliche und unternehmerische Aktivitäten und setzen sich für Transparenz und Rechenschaftspflicht ein. Sie spielen oft eine Rolle als „Watchdog“, indem sie Missstände und Menschenrechtsverletzungen aufdecken und die Öffentlichkeit über problematische Entwicklungen informieren"}, {"kategorie": "", "text": "Viele NGOs vertreten ihre Anliegen gegenüber politischen Entscheidungsträgern ([[Lobbying]]) und nehmen aktiv an der Gestaltung der [[Gesetzgebung]] teil. Sie bringen ihre Expertise in politische Debatten ein und treten für gesetzliche Maßnahmen ein, die ihre Ziele unterstützen"}, {"kategorie": "", "text": "Einige NGOs leisten direkte Hilfe für Menschen in Notlagen, zum Beispiel durch Unterstützung für Obdachlose, Flüchtlinge oder Opfer von Naturkatastrophen. Organisationen wie Caritas und Rotes Kreuz bieten etwa Beratungsangebote, medizinische Versorgung und Hilfsprojekte im In- und Ausland an"}, {"kategorie": "", "text": "Die Finanzierung von NGOs erfolgt durch verschiedene Quellen, darunter Spenden, Fördergelder, Mitgliedsbeiträge und gelegentlich auch staatliche Zuschüsse. Staatliche Mittel dürfen jedoch nicht zu einer Abhängigkeit oder zu einem Verlust der Unabhängigkeit führen. Viele NGOs in Österreich sind als [[Vereine]] organisiert und müssen die Anforderungen des [[Vereinsrechts]] erfüllen, was Transparenz und Rechenschaftspflicht unterstützt."}]'::jsonb, ''),
  ('varein', 'Varein', '', '', '', '', 'Verein', '[{"kategorie": "allg.", "text": "\"rechtlich anerkannter, freiwilliger und dauerhafter Verband von Personen, die zur Verfolgung eines bestimmten gemeinsamen Zwecks gegründet wird\""}, {"kategorie": "", "text": "Dieser Zweck kann sozialer, kultureller, sportlicher, politischer oder anderer Art sein und muss gemeinnützig oder zumindest nicht primär auf Gewinnerzielung ausgerichtet sein"}, {"kategorie": "", "text": "Die rechtliche Grundlage für Vereine in Österreich bildet das Österreichische [[Vereinsgesetz]], das die Gründung, Struktur, Pflichten und Rechte von Vereinen regelt"}, {"kategorie": "", "text": "Merkmale eines Vereins: (i) [[Rechtspersönlichkeit]]: Ein eingetragener Verein gilt in Österreich als [[juristische]] Person. Das bedeutet, der Verein kann selbstständig Verträge abschließen, Vermögen besitzen und vor Gericht klagen oder verklagt werden;  (ii) Die Mitgliedschaft in einem Verein ist freiwillig, und der Verein ist unabhängig von staatlicher oder wirtschaftlicher Kontrolle, was seine Autonomie und Selbstverwaltung sicherstellt;  (iii) Vereine in Österreich verfolgen häufig gemeinnützige oder ideelle Zwecke, wie die Förderung des Sports, der Kunst, der Wissenschaft oder sozialer Projekte. Ein Verein darf wirtschaftliche Tätigkeiten ausüben, solange diese dem Vereinszweck untergeordnet bleiben und nicht primär auf Gewinn ausgerichtet sind;  (iv) Selbstverwaltung: Vereine organisieren sich selbstständig, das heißt, sie bestimmen ihre eigenen Ziele und Regeln im Rahmen des Vereinsgesetzes und ihrer eigenen Statuten"}, {"kategorie": "", "text": "Die Gründung eines Vereins erfolgt durch mindestens zwei Personen, die sich auf gemeinsame Vereinsstatuten einigen, in denen Ziele, Organisation und Tätigkeiten des Vereins festgelegt werden. Die Statuten müssen wesentliche Punkte enthalten, wie den Vereinszweck, die Mitgliedschaftsregelungen, die Struktur der Vereinsorgane (z. B. Vorstand und Generalversammlung) und die Regeln zur Finanzierung"}, {"kategorie": "", "text": "Ein Verein erlangt seine Rechtspersönlichkeit durch die Eintragung ins Zentrale Vereinsregister (ZVR), das vom Bundesministerium für Inneres geführt wird. Nach der Einreichung der Statuten prüft die Behörde, ob der Vereinszweck den gesetzlichen Anforderungen entspricht und keine Bedenken bestehen. Wenn die Eintragung erfolgt, gilt der Verein als offiziell gegründet"}, {"kategorie": "", "text": "Die wesentlichen Organe eines Vereins sind: (i) Generalversammlung: Die Generalversammlung ist das höchste Organ des Vereins, in dem alle Mitglieder stimmberechtigt sind. Sie findet mindestens einmal jährlich statt und entscheidet über wichtige Angelegenheiten des Vereins, wie die Wahl des Vorstands und die Genehmigung des Budgets;  (ii) Vorstand: Der Vorstand ist das geschäftsführende Organ des Vereins, das vom Obmann bzw. der Obfrau geleitet wird und für die operative Leitung und Verwaltung zuständig ist. Er wird von der Generalversammlung gewählt und setzt die Beschlüsse der Mitglieder um;  (iii) Kassier: Vereine sind verpflichtet, mindestens einen Kassier (Rechnungsprüfer) zu haben, der die finanzielle Gebarung kontrolliert und der Generalversammlung Bericht erstattet"}, {"kategorie": "", "text": "Der Verein muss seine Finanzgebarung ordentlich dokumentieren und einmal jährlich der Generalversammlung Bericht erstatten. Die Einhaltung der Vereinssatzung und die ordnungsgemäße Verwaltung müssen sichergestellt sein. Änderungen in den Statuten sowie die Abberufung des Vorstands/Obmanns sind der Behörde zu melden"}, {"kategorie": "", "text": "Vereine finanzieren sich meist durch Mitgliedsbeiträge, Spenden, Sponsoring und eventuelle Einnahmen aus Veranstaltungen oder Projekten. Auch öffentliche Förderungen und Zuschüsse können beantragt werden, insbesondere wenn der Verein gemeinnützige Zwecke verfolgt. Gewinne müssen dem Vereinszweck zugutekommen und dürfen nicht an die Mitglieder ausgeschüttet werden."}]'::jsonb, ''),
  ('vareinsrecht', 'Vareinsrecht', '', '', '', '', 'Vereinsrecht', '[{"kategorie": "jur.", "text": "\"alle gesetzlichen Regelungen, welche die Gründung, Organisation, Verwaltung und Auflösung von Vereinen betreffen\""}, {"kategorie": "", "text": "Das Vereinsrecht regelt die Rechte und Pflichten von Vereinsmitgliedern und Organen und stellt sicher, dass Vereine ihre Tätigkeiten in einem rechtlich geordneten Rahmen ausüben können"}, {"kategorie": "", "text": "Die zentrale gesetzliche Grundlage für das Vereinsrecht bildet das österreichische [[Vereinsgesetz]] 2002 (VereinsG), das die rechtlichen Rahmenbedingungen für die Tätigkeit von Vereinen schafft und deren rechtliche Stellung als [[juristische]] Person definiert"}, {"kategorie": "", "text": "Die Vereinsfreiheit ist ein verfassungsrechtlich geschütztes Grundrecht in Österreich und garantiert das Recht, Vereine zu gründen und sich in Vereinen zu betätigen, solange der Vereinszweck legal und mit den Grundwerten der Gesellschaft vereinbar ist. Vereine können für soziale, kulturelle, sportliche, politische oder andere nicht gewinnorientierte Zwecke gegründet werden"}, {"kategorie": "", "text": "Ein eingetragener Verein hat die Rechtsform einer [[juristischen]] Person und ist somit selbst Träger von Rechten und Pflichten. Er kann Verträge abschließen, Eigentum besitzen, klagen und verklagt werden. Durch die Eintragung ins Zentrale Vereinsregister (ZVR) erlangt ein Verein seine [[Rechtspersönlichkeit]]"}, {"kategorie": "", "text": "Zur Gründung eines Vereins sind mindestens zwei Personen erforderlich, die sich auf Vereinsstatuten einigen, in denen der Zweck, die Organe und die innere Struktur des Vereins festgelegt sind. Die Gründung erfolgt durch Eintragung im Zentralen Vereinsregister, wobei die Statuten bei der zuständigen Behörde eingereicht und geprüft werden"}, {"kategorie": "", "text": "Das österreichische Vereinsrecht sieht bestimmte Organe vor, die für die Leitung und Kontrolle des Vereins zuständig sind: (i) Generalversammlung;  (ii) Vorstand/Obmann;  (iii) Kassier (Rechnungsprüfer), siehe [[Verein]]"}, {"kategorie": "", "text": "Die Bedingungen für den Erwerb und die Beendigung der Mitgliedschaft sind in den Statuten festgelegt.\nMitglieder haben das Recht, an der Generalversammlung teilzunehmen und abzustimmen. Sie können über wichtige Vereinsentscheidungen mitbestimmen und den Vorstand wählen"}, {"kategorie": "", "text": "Vereine finanzieren sich durch Mitgliedsbeiträge, Spenden, Sponsoring und öffentliche Fördermittel. Einnahmen müssen für den Vereinszweck verwendet werden, da Vereine gemeinnützige oder ideelle Zwecke verfolgen und nicht primär gewinnorientiert sind"}, {"kategorie": "", "text": "Der Verein als juristische Person haftet für seine Verbindlichkeiten. Vereinsorgane wie der Vorstand/Obmann haften im Allgemeinen nicht persönlich, sofern sie im Rahmen der Vereinsstatuten und gesetzeskonform handeln. Bei grober Fahrlässigkeit oder vorsätzlichem Fehlverhalten können Vorstandsmitglieder jedoch zur Verantwortung gezogen werden"}, {"kategorie": "", "text": "Das Vereinsrecht regelt auch die Beendigung des Vereins durch freiwillige Auflösung, behördliche Auflösung oder durch Insolvenz. Bei einer freiwilligen Auflösung entscheidet die Generalversammlung, und der Verein muss seine Vermögenswerte entsprechend den Vereinsstatuten oder gesetzlichen Vorschriften abwickeln. Häufig wird festgelegt, dass Restvermögen an gemeinnützige Organisationen oder andere Vereine gehen soll."}]'::jsonb, ''),
  ('vareinsgesetz', 'Vareinsgesetz', '', '', '', '', 'Vereinsgesetz', '[{"kategorie": "", "text": "Das Vereinsgesetz regelt alle wesentlichen Aspekte des Vereinswesens und bietet einen rechtlichen Rahmen, der die Vereinsfreiheit und die Selbstverwaltung der Vereine schützt"}, {"kategorie": "", "text": "Vereinsfreiheit: Das Vereinsgesetz sichert das Recht, Vereine zu gründen und sich in Vereinen zu organisieren, unabhängig davon, ob der Zweck sozialer, kultureller, sportlicher oder anderer Art ist. Die Vereinsfreiheit ist ein verfassungsrechtlich geschütztes Recht in Österreich, und das Vereinsgesetz stellt sicher, dass diese Freiheit gewahrt bleibt"}, {"kategorie": "", "text": "Das Vereinsgesetz legt fest, wie Vereine gegründet und geführt werden sollen, welche Rechte und Pflichten sie haben und wie sie ihre Tätigkeiten auf rechtlich geordnete Weise ausführen können (siehe hierzu auch [[Verein]] bzw. [[Vereinsrecht]])"}]'::jsonb, ''),
  ('rechtspeasoenlichkeit', 'Rechtspeasönlichkeit', '', '', '', '', 'Rechtspersönlichkeit', '[{"kategorie": "jur.", "text": "\"Fähigkeit einer juristischen oder natürlichen Person, Träger von Rechten und Pflichten zu sein\""}, {"kategorie": "", "text": "Mit der Rechtspersönlichkeit ist eine eigenständige rechtliche Existenz verbunden, die es ermöglicht, Verträge abzuschließen, Eigentum zu besitzen und vor Gericht zu klagen oder verklagt zu werden"}, {"kategorie": "", "text": "Diese Fähigkeit zur Teilnahme am Rechtsverkehr ist ein grundlegendes Konzept des [[Zivilrechts]] und bildet die Basis für das eigenständige Handeln im Rechtsrahmen"}, {"kategorie": "", "text": "Arten der Rechtspersönlichkeit: (i) [[Natürliche]] Personen: Jeder Mensch erlangt mit der Geburt die Rechtspersönlichkeit und besitzt diese bis zum Tod. Natürliche Personen können daher Verträge abschließen, Eigentum erwerben und haben Rechte und Pflichten;  (ii) [[Juristische]] Personen: Juristische Personen sind keine Menschen, sondern rechtlich anerkannte Organisationen oder Zusammenschlüsse, die eine eigene Rechtspersönlichkeit besitzen. Beispiele dafür sind Unternehmen (z. B. GmbHs, AGs), [[Vereine]] und [[Stiftungen]]. Die Rechtspersönlichkeit erlaubt diesen Organisationen, unabhängig von ihren Mitgliedern rechtlich zu handeln. Für juristische Personen ist die Rechtspersönlichkeit oft an bestimmte rechtliche Vorgänge gebunden, wie z. B. die Eintragung in ein öffentliches Register. Ein Verein in Österreich etwa erlangt Rechtspersönlichkeit durch die Eintragung in das Zentrale Vereinsregister (ZVR). Eine GmbH erlangt sie durch die Eintragung ins Firmenbuch"}, {"kategorie": "", "text": "Die Rechtspersönlichkeit ermöglicht es deren Inhabern, eigenständig am Rechtsleben teilzunehmen. Dies bedeutet, dass juristische Personen Verträge schließen, Verbindlichkeiten eingehen und Rechte erwerben kann, unabhängig von den natürlichen Personen, die hinter ihr stehen. Rechtspersönlichkeit schafft so Klarheit und Sicherheit im Rechtsverkehr und erlaubt es, Rechte und Pflichten klar einer Person oder Organisation zuzuordnen"}, {"kategorie": "", "text": "Natürliche Personen verlieren ihre Rechtspersönlichkeit mit dem Tod. Juristische Personen verlieren ihre Rechtspersönlichkeit durch Auflösung und Liquidation, zum Beispiel wenn ein Unternehmen im Firmenbuch gelöscht oder ein Verein aufgelöst wird."}]'::jsonb, ''),
  ('lobbying', 'Lobbying', '', '', '', '', 'Lobbying', '[{"kategorie": "allg.", "text": "\"der Versuch, politische Entscheidungen und Gesetzgebungsprozesse zu beeinflussen, um bestimmte Interessen, Positionen oder Anliegen zu vertreten\""}, {"kategorie": "", "text": "Lobbying wird von [[Interessenvertretern]] durchgeführt, die im Auftrag von Organisationen, Unternehmen, Berufsverbänden, Gewerkschaften oder Nichtregierungsorganisationen (NGOs) handeln"}, {"kategorie": "", "text": "Ziel des Lobbyings ist es, Gesetzgeber und Regierungsvertreter dazu zu bewegen, politische Entscheidungen im Sinne der vertretenen Interessen zu treffen. Dies kann von wirtschaftlichen Interessen (z. B. einer Industrie) bis hin zu sozialen Anliegen (z. B. Umweltschutz oder Menschenrechte) reichen"}, {"kategorie": "", "text": "Lobbyisten agieren oft als Informationsquelle für politische Entscheidungsträger und bieten Fachwissen zu bestimmten Themen an. Sie stellen Argumente, Daten und Analysen bereit, um Entscheidungsträger zu beeinflussen und ihre Interessen als Lösungsvorschläge zu präsentieren"}, {"kategorie": "", "text": "Lobbying erfolgt durch direkten Kontakt mit Politikern, Ministerien, Ausschüssen und anderen politischen Akteuren. Diese Beziehungen ermöglichen es Lobbyisten, frühzeitig auf Gesetzgebungsprozesse Einfluss zu nehmen"}, {"kategorie": "", "text": "Neben persönlichen Gesprächen nutzen Lobbyisten auch Schriftwechsel, öffentliche Kampagnen, Medienarbeit, Konferenzen und Fachveranstaltungen, um ihre Anliegen zu kommunizieren. Manche betreiben auch „Grassroots-Lobbying“, das darauf abzielt, die öffentliche Meinung zu mobilisieren und Druck auf politische Akteure auszuüben"}, {"kategorie": "", "text": "Beispiele von Lobbying-Akteuren:  (i) Wirtschaftsverbände und Kammern (z. B. [[Wirtschaftskammer]], [[Industriellenvereinigung]]);  (ii) Gewerkschaften und Berufsverbände (z. B. [[Österreichischer]] Gewerkschaftsbund);  (iii) [[Nichtregierungsorganisationen]] (NGOs) (z. B. Umwelt- und Menschenrechtsorganisationen wie Greenpeace);  (iv) Unternehmen und Industrien (z. B. Pharma-, Energie- oder Digitalindustrie)"}, {"kategorie": "", "text": "Um Transparenz und ethische Standards im Lobbying sicherzustellen, haben viele Länder, darunter auch Österreich, folgende Regelungen eingeführt: (i) Lobbying- und Interessenvertretungsgesetz (LobbyG): In Österreich regelt das Lobbying- und Interessenvertretungsgesetz den Ablauf von Lobbyingtätigkeiten. Es schreibt vor, dass Lobbyisten sich registrieren lassen und bestimmte Verhaltensregeln einhalten müssen, etwa zur Transparenz und Offenlegung von Interessen;  (ii) Lobbyistenregister: Lobbyisten müssen sich in einem Lobbyistenregister eintragen, das öffentlich zugänglich ist. Dieses Register gibt Auskunft darüber, welche Interessen vertreten werden und welche Unternehmen oder Organisationen dahinterstehen."}]'::jsonb, ''),
  ('augenschein', 'Augenschein', '', '', '', '', 'Augenschein', '[{"kategorie": "jur.", "text": "\"Beweisaufnahme durch sinnliche Wahrnehmung in einem [[Gerichtsverfahren]]\""}, {"kategorie": "", "text": "Hierbei verschafft sich das Gericht oder die zuständige Behörde durch eigenes Beobachten und Betrachten eines Gegenstands, eines Ortes oder eines Zustands einen unmittelbaren Eindruck, um relevante Tatsachen festzustellen"}, {"kategorie": "", "text": "Der Augenschein zählt zu den sogenannten unmittelbaren Beweismitteln und wird vor allem im [[Straf-]] und Zivilrecht angewandt"}, {"kategorie": "", "text": "Der Augenschein dient dazu, dem Gericht durch eigene Anschauung ein Bild von den tatsächlichen Gegebenheiten zu verschaffen, anstatt sich nur auf Aussagen oder Dokumente zu stützen. Beispiele sind die Besichtigung eines Unfallorts, die Untersuchung eines beschädigten Gegenstands oder die Betrachtung von Videoaufnahmen"}, {"kategorie": "", "text": "Häufig ergänzt der Augenschein andere Beweismittel wie Zeugen- oder Sachverständigenaussagen und dient dazu, deren Richtigkeit zu überprüfen oder zu unterstützen"}, {"kategorie": "", "text": "Der Augenschein wird in der Regel protokolliert, und es können auch Fotografien, Videoaufnahmen oder Skizzen angefertigt werden, um die Feststellungen zu dokumentieren. Dies ermöglicht es, die Beobachtungen auch in späteren Verfahrensabschnitten zu berücksichtigen"}, {"kategorie": "", "text": "Der Augenschein wird entweder vom [[Gericht]] selbst durchgeführt oder es wird ein [[Sachverständiger]] beauftragt, der den Augenschein nimmt und dem Gericht darüber berichtet"}, {"kategorie": "", "text": "Arten des Augenscheins:  (i) Lokalaugenschein: Bei einem Lokalaugenschein besichtigt das Gericht den Ort, an dem sich ein bestimmtes Ereignis zugetragen hat, beispielsweise den Tatort eines Verbrechens, einen Unfallort oder ein Bauwerk im Rahmen eines Zivilprozesses;  (ii) Der Augenschein kann auch an Gegenständen oder Objekten genommen werden, etwa an einem beschädigten Fahrzeug, an Werkzeugen oder an schriftlichen Dokumenten (z. B. zur Prüfung der Echtheit);  (iii) Personenbezogener Augenschein: In bestimmten Fällen kann ein Augenschein auch an Personen genommen werden, beispielsweise bei einer Identifizierung oder bei der Überprüfung von Verletzungen"}, {"kategorie": "", "text": "Der Augenschein hat eine wichtige Beweisfunktion, da er das Gericht in die Lage versetzt, objektive Tatsachen selbstständig festzustellen. Er ist ein unmittelbares Beweismittel, das oft eine ergänzende Klarheit schafft, wenn Zeugenaussagen oder andere Beweismittel unklar oder widersprüchlich sind."}]'::jsonb, ''),
  ('kollektivvatrog', 'Kollektivvatrog', '', '', '', '', 'Kollektivvertrag', '[{"kategorie": "allg.", "text": "\"schriftlicher Vertrag zwischen Arbeitgeberverbänden (oder einzelnen Arbeitgebern) und [[Gewerkschaften]], der die arbeitsrechtlichen Rahmenbedingungen für bestimmte Branchen oder Berufsgruppen regelt\""}, {"kategorie": "", "text": "Der Kollektivvertrag wird in Verhandlungen zwischen den [[Sozialpartnern]] ausgehandelt und legt verbindliche Mindeststandards für Arbeitsbedingungen, Löhne und Gehälter, Arbeitszeiten, Urlaubsansprüche und weitere arbeitsrechtliche Regelungen fest, d.h. Arbeitnehmer dürfen durch individuelle Arbeitsverträge nicht schlechter gestellt werden als im Kollektivvertrag festgelegt"}, {"kategorie": "", "text": "Kollektivverträge gelten meist für bestimmte Branchen (z. B. Handel, Baugewerbe, Gastronomie) oder Berufsgruppen. Jeder Arbeitnehmer, der in den Geltungsbereich des Kollektivvertrags fällt, hat automatisch Anspruch auf die darin festgelegten Regelungen"}, {"kategorie": "", "text": "In Österreich ist der Kollektivvertrag traditionell durch die [[Sozialpartnerschaft]] geprägt. Die Verhandlungen werden üblicherweise zwischen der [[Wirtschaftskammer]] Österreich (WKÖ) als Vertretung der Arbeitgeber und dem [[Österreichischen]] Gewerkschaftsbund (ÖGB) als Vertretung der Arbeitnehmer geführt. In einzelnen Branchen können jedoch auch spezifische Fachverbände und Berufsgruppen eigene Verhandlungen führen"}, {"kategorie": "", "text": "Kollektivverträge werden regelmäßig neu verhandelt, oft jährlich, um Anpassungen an die wirtschaftliche Lage und Inflation vorzunehmen und die Interessen der Arbeitnehmer und Arbeitgeber zu wahren"}, {"kategorie": "", "text": "Ein Kollektivvertrag enthält typischerweise Bestimmungen zu folgenden Bereichen:  (i) Löhne und Gehälter: Festlegung der Mindestlöhne und -gehälter für verschiedene Berufskategorien und Tätigkeitsgruppen. Diese Lohn- und Gehaltstabellen sind ein wesentlicher Bestandteil des Kollektivvertrags;  (ii) Arbeitszeitregelungen: Festlegung der Normalarbeitszeit, Regelungen zu Überstunden, Pausen und möglichen Schichtarbeitsmodellen;  (iii) Urlaubs- und Weihnachtsgeld: Der Kollektivvertrag regelt in der Regel Sonderzahlungen wie das Urlaubs- und Weihnachtsgeld (13. und 14. Monatsgehalt), die für viele Arbeitnehmer in Österreich zur Praxis gehören;  (iv) Kündigungsfristen und -bedingungen: Festlegung der Kündigungsfristen und -regelungen für Arbeitnehmer und Arbeitgeber innerhalb des Geltungsbereichs des Kollektivvertrags;  (v) Sonderregelungen: Je nach Branche können Kollektivverträge auch spezifische Regelungen enthalten, etwa zu Arbeitskleidung, Reisekosten, Weiterbildung oder Arbeitsbedingungen in besonderen Arbeitsumgebungen"}, {"kategorie": "", "text": "Der Kollektivvertrag gilt grundsätzlich für alle Arbeitnehmer, deren Arbeitsverhältnisse unter den räumlichen und fachlichen Geltungsbereich des Kollektivvertrags fallen. Dies bedeutet, dass alle Betriebe, die Mitglied des entsprechenden Arbeitgeberverbands (z. B. einer Sparte der Wirtschaftskammer) sind, zur Anwendung des Kollektivvertrags verpflichtet sind"}, {"kategorie": "", "text": "[[Sozialpartnerschaft]] und sozialer Frieden: Die Verhandlung von Kollektivverträgen fördert das Zusammenspiel der Sozialpartner und den sozialen Frieden, da Konflikte über Arbeitsbedingungen auf eine formalisierte und oft einvernehmliche Weise gelöst werden."}]'::jsonb, ''),
  ('kollektivvatrogsvahaundlungan', 'Kollektivvatrogsvahaundlungan', '', '', '', '', 'Kollektivvertragsverhandlungen', '[{"kategorie": "allg.", "text": "\"strukturierte Verhandlungen zwischen Arbeitgebervertretern ([[Wirtschaftskammer]]) und Arbeitnehmervertretern ([[Gewerkschaften]]), die das Ziel haben, einen neuen [[Kollektivvertrag]] abzuschließen oder bestehende Vereinbarungen anzupassen\""}, {"kategorie": "", "text": "Diese Verhandlungen dienen dazu, verbindliche Standards für Arbeitsbedingungen, Löhne und Gehälter, Arbeitszeiten, Urlaubsansprüche und weitere arbeitsrechtliche Regelungen in einer bestimmten Branche oder für eine Berufsgruppe festzulegen"}, {"kategorie": "", "text": "In Österreich sind die Kollektivvertragsverhandlungen ein zentraler Bestandteil der [[Sozialpartnerschaft]]"}, {"kategorie": "", "text": "Kollektivvertragsverhandlungen werden regelmäßig geführt, um die Arbeitsbedingungen an die aktuellen wirtschaftlichen Rahmenbedingungen anzupassen, wie z. B. die Inflation, konjunkturelle Entwicklungen und Branchenbesonderheiten. In vielen Branchen finden Kollektivvertragsverhandlungen daher jährlich statt"}, {"kategorie": "", "text": "Ablauf der Kollektivvertragsverhandlungen: (i) Beide Seiten bereiten sich auf die Verhandlungen vor, indem sie Forderungen und Positionen formulieren, die auf Analysen der aktuellen wirtschaftlichen Situation und auf Branchenbedürfnissen basieren. Die Gewerkschaften fordern in der Regel Gehaltserhöhungen und Verbesserungen der Arbeitsbedingungen, während die Arbeitgeberseite wirtschaftliche Stabilität und vertretbare Lohnerhöhungen im Fokus hat;  (ii) Die Verhandlungen beginnen mit der Präsentation der jeweiligen Forderungen und Erwartungen. Es folgen Gespräche, in denen über Gehälter, Arbeitszeiten, Urlaubsansprüche und andere arbeitsrelevante Bedingungen diskutiert wird. Dabei geht es oft um Kompromisse zwischen den Positionen der Arbeitgeber und Arbeitnehmer;  (iii) Die Verhandlungen können sich über mehrere Runden erstrecken und sind abgeschlossen, wenn beide Seiten einen Kompromiss gefunden haben. Gelingt dies, wird der neue Kollektivvertrag schriftlich fixiert und tritt mit dem festgelegten Zeitpunkt in Kraft;  (iv) Falls keine Einigung erzielt wird, können Schlichtungsstellen oder Mediatoren hinzugezogen werden. Kommt es dennoch zu keiner Lösung, können die Gewerkschaften Streiks organisieren, um den Druck auf die Arbeitgeberseite zu erhöhen"}, {"kategorie": "", "text": "In Österreich werden Kollektivvertragsverhandlungen traditionell zwischen den [[Sozialpartnern]] geführt:  (i) \nArbeitnehmervertreter: In der Regel ist dies der [[Österreichische]] Gewerkschaftsbund (ÖGB) oder spezifische Fachgewerkschaften, die die Interessen der Arbeitnehmer vertreten und Forderungen hinsichtlich Lohnanpassungen und Arbeitsbedingungen einbringen;  (ii) Arbeitgebervertreter: Die Arbeitgeberseite wird in der Regel von der [[Wirtschaftskammer]] Österreich (WKÖ) vertreten. In bestimmten Branchen oder Berufsgruppen kann auch ein anderer Arbeitgeberverband die Verhandlungen führen."}]'::jsonb, ''),
  ('diskriminiirungsvabot', 'Diskriminiirungsvabot', '', '', '', '', 'Diskriminierungsverbot', '[{"kategorie": "jur.", "text": "\"zentraler Rechtsgrundsatz, der es verbietet, Personen aufgrund bestimmter geschützter Merkmale ungleich zu behandeln oder zu benachteiligen\""}, {"kategorie": "", "text": "Das Diskriminierungsverbot ist ein wichtiges Element des Gleichheitsgrundsatzes und wird in verschiedenen Gesetzen festgeschrieben, die Chancengleichheit und Gleichbehandlung sicherstellen sollen"}, {"kategorie": "", "text": "Es umfasst sowohl den Schutz vor Diskriminierung im Arbeitsleben als auch in anderen Lebensbereichen wie Waren- und Dienstleistungszugang, Bildung und Wohnen"}, {"kategorie": "", "text": "Verfassungsrechtliche Verankerung: (i) Die [[österreichische]] Bundesverfassung enthält das allgemeine Gleichheitsgebot, das besagt, dass alle Menschen vor dem Gesetz gleich sind. Dieses Prinzip verbietet eine willkürliche Ungleichbehandlung durch staatliche Stellen und garantiert gleichen Schutz und gleiche Rechte;  (ii) [[Gleichbehandlungsgesetz]] (GlBG): Das Gleichbehandlungsgesetz ist die zentrale gesetzliche Grundlage für das Diskriminierungsverbot im privaten und beruflichen Bereich. Es verbietet Diskriminierungen am Arbeitsplatz und im Zugang zu Waren und Dienstleistungen aufgrund von Geschlecht, ethnischer Herkunft, Religion, Weltanschauung, Alter und sexueller Orientierung;  (iii) [[Europäische]] Menschenrechtskonvention (EMRK): Die EMRK, die in Österreich Verfassungsrang hat, enthält ebenfalls ein Diskriminierungsverbot. Artikel 14 der EMRK garantiert das Recht, die festgelegten Freiheiten und Rechte ohne Diskriminierung aufgrund von Merkmalen wie Geschlecht, Religion oder politischer Überzeugung in Anspruch zu nehmen;  (iv) Behindertengleichstellungsgesetz: Zusätzlich schützt das Behindertengleichstellungsgesetz Menschen mit Behinderungen vor Diskriminierung und verpflichtet private und öffentliche Einrichtungen, angemessene Vorkehrungen zu treffen, um Chancengleichheit für Menschen mit Behinderungen zu gewährleisten"}, {"kategorie": "", "text": "In Österreich stehen mehrere Möglichkeiten zur Verfügung, um Diskriminierungsfälle zu melden und zu klären: (i) [[Gleichbehandlungsanwaltschaft]]: Die Gleichbehandlungsanwaltschaft bietet Beratung und Unterstützung für Personen, die Diskriminierung erfahren haben. Sie prüft Diskriminierungsfälle, gibt Empfehlungen ab und kann Verfahren vor der Gleichbehandlungskommission einleiten;  (ii) [[Gleichbehandlungskommission]]: Die Gleichbehandlungskommission ist ein unabhängiges Organ, das Diskriminierungsfälle prüft und verbindliche Gutachten abgibt. Sie vermittelt zwischen den Parteien und kann eine Diskriminierung feststellen, was eine Grundlage für rechtliche Ansprüche schafft;  (iii) \nGerichtliche [[Klage]]: Personen, die Diskriminierung erfahren haben, können Schadenersatz oder Entschädigung einklagen. Das [[Gleichbehandlungsgesetz]] sieht Schadenersatzansprüche vor, wenn eine Diskriminierung festgestellt wird."}]'::jsonb, ''),
  ('willkueavabot', 'Willküavabot', '', '', '', '', 'Willkürverbot', '[{"kategorie": "jur.", "text": "\"grundlegendes Prinzip im österreichischen [[Rechtsstaat]], welches besagt, dass staatliche Organe und Behörden in ihren Entscheidungen und Handlungen nicht willkürlich und ohne sachlichen Grund handeln dürfen\""}, {"kategorie": "", "text": "Das Willkürverbot schützt Bürger vor ungerechtfertigten Eingriffen und unbegründeter Ungleichbehandlung durch den [[Staat]] und seine Institutionen und ist ein zentraler Bestandteil des [[Gleichheitsgrundsatzes]] und der [[Rechtsstaatlichkeit]] in Österreich"}, {"kategorie": "", "text": "Das Willkürverbot leitet sich aus dem allgemeinen Gleichheitssatz ab, der in der [[österreichischen]] Bundesverfassung verankert ist. Dieser Gleichheitssatz garantiert, dass alle Menschen vor dem Gesetz gleich sind und dass staatliches Handeln auf sachlichen und nachvollziehbaren Kriterien basieren muss"}, {"kategorie": "", "text": "Die [[Europäische]] Menschenrechtskonvention sichert das Willkürverbot durch das [[Diskriminierungsverbot]] und das [[Recht]] auf ein faires Verfahren ab. Österreich ist an die EMRK gebunden, wodurch der Schutz vor willkürlichem staatlichem Handeln zusätzlich auf europäischer Ebene gesichert wird"}, {"kategorie": "", "text": "Der österreichische [[Verfassungsgerichtshof]] (VfGH) hat das Willkürverbot in zahlreichen Entscheidungen konkretisiert. Er prüft Verwaltungsakte und Gesetzesentscheidungen daraufhin, ob sie sachlich gerechtfertigt und nicht willkürlich sind. Wenn der VfGH willkürliches Handeln feststellt, kann er die Entscheidung aufheben oder die Verfassungswidrigkeit feststellen"}, {"kategorie": "", "text": "Das Willkürverbot gilt insbesondere dann, wenn Behörden über einen Ermessensspielraum verfügen. Auch in Ermessensentscheidungen müssen sachliche und nachvollziehbare Kriterien angelegt werden, und die Entscheidung darf nicht auf persönlichen Präferenzen oder unzulässigen Gründen basieren"}, {"kategorie": "", "text": "Der Verfassungsgerichtshof ist das zentrale Kontrollorgan für die Einhaltung des Willkürverbots. [[Bürger]] können eine [[Beschwerde]] an den VfGH richten, wenn sie der Meinung sind, dass ein Akt der öffentlichen Gewalt sie willkürlich benachteiligt hat. Der VfGH kann Entscheidungen, die als willkürlich eingestuft werden, aufheben"}, {"kategorie": "", "text": "Der [[Verwaltungsgerichtshof]] prüft ebenfalls die Entscheidungen der Verwaltungsbehörden auf ihre Rechtmäßigkeit und darauf, ob sie dem Willkürverbot entsprechen"}, {"kategorie": "", "text": "In Fällen, in denen das nationale [[Rechtsmittel]] ausgeschöpft ist, kann der [[Europäische]] Gerichtshof für Menschenrechte (EGMR) angerufen werden. Der EGMR überprüft, ob das Willkürverbot, wie es in der EMRK verankert ist, verletzt wurde."}]'::jsonb, ''),
  ('vafossungsgerichtshof', 'Vafossungsgerichtshof', '', '', '', '', 'Verfassungsgerichtshof', '[{"kategorie": "", "text": "Der Verfassungsgerichtshof ist ein unabhängiges und weisungsfreies Gericht, dessen Hauptaufgabe es ist, über die Einhaltung der österreichischen [[Verfassung]] zu wachen und sicherzustellen, dass alle staatlichen Akte, Gesetze und Verordnungen im Einklang mit der Verfassung stehen"}, {"kategorie": "", "text": "Der VfGH ist damit ein zentrales Organ des österreichischen [[Rechtsstaates]] und schützt die Grundrechte der Bürger sowie die demokratischen Prinzipien"}, {"kategorie": "", "text": "Aufgaben und Zuständigkeiten des Verfassungsgerichtshofs:  (i) Gesetzesprüfung: Der VfGH überprüft, ob [[Gesetze]] und [[Verordnungen]] mit der Verfassung übereinstimmen. Falls der VfGH feststellt, dass ein Gesetz oder eine Verordnung verfassungswidrig ist, kann er diese aufheben. Dadurch wird sichergestellt, dass die [[Gesetzgebung]] die Verfassungsgrundsätze einhält;  (ii) Schutz der Grundrechte: Der VfGH ist der zentrale Hüter der [[Grund-]] und Freiheitsrechte in Österreich. Bürger können eine [[Beschwerde]] beim VfGH einreichen, wenn sie sich durch Entscheidungen von [[Verwaltungsbehörden]] in ihren Grundrechten verletzt fühlen. Der VfGH kann solche Entscheidungen aufheben und dadurch den Schutz der Grundrechte gewährleisten;  (iii) Wahlprüfung: Der VfGH prüft die Gültigkeit von Wahlen auf Bundes-, Landes- und Gemeindeebene sowie Volksabstimmungen und Volksbefragungen. Bei festgestellten Unregelmäßigkeiten oder Verstößen kann er die Wahl ganz oder teilweise für ungültig erklären und eine Wiederholung anordnen;  (iv) Prüfung von Staatsverträgen: Der VfGH überprüft, ob Staatsverträge, die Österreich abschließt, mit der Verfassung vereinbar sind. Er kann Staatsverträge, die gegen verfassungsrechtliche Bestimmungen verstoßen, für verfassungswidrig erklären;  (v) Kompetenzkonflikte: Der VfGH entscheidet über Kompetenzkonflikte zwischen obersten Staatsorganen oder zwischen [[Bund]] und [[Ländern]]. Diese Konflikte treten auf, wenn unterschiedliche staatliche Stellen unterschiedliche Zuständigkeiten beanspruchen oder in Streit darüber geraten, wer bestimmte Entscheidungen treffen darf"}, {"kategorie": "", "text": "Der Verfassungsgerichtshof besteht aus dem Präsidenten, dem Vizepräsidenten und insgesamt 12 weiteren Mitgliedern sowie 6 Ersatzmitgliedern. Die Mitglieder werden vom [[Bundespräsidenten]] auf Vorschlag der [[Bundesregierung]], des [[Nationalrats]] und des [[Bundesrats]] ernannt. Die Amtszeit der Mitglieder des Verfassungsgerichtshofs endet spätestens mit 70 Jahren. Die Mitglieder sind in ihrer Tätigkeit weisungsfrei und unabhängig und unterliegen nur den gesetzlichen Bestimmungen"}, {"kategorie": "", "text": "Der Verfassungsgerichtshof kann entweder von sich aus tätig werden oder durch Anträge und Beschwerden angestoßen werden, die von betroffenen Bürgern, politischen Parteien, Behörden oder anderen staatlichen Stellen eingebracht werden"}, {"kategorie": "", "text": "Zu den wichtigsten Verfahrensarten gehören: (i) Individualbeschwerde: Bürger können eine Beschwerde einreichen, wenn sie durch eine Entscheidung einer Verwaltungsbehörde in ihren Grundrechten verletzt wurden;  (ii) Gesetzesprüfungsverfahren: Verschiedene staatliche Organe (z. B. Bundesregierung, Landesregierungen) können ein Gesetzesprüfungsverfahren einleiten;  (iii) Wahlprüfungsverfahren: Anfechtung von Wahlen durch berechtigte Stellen, wenn Unregelmäßigkeiten vermutet werden"}, {"kategorie": "", "text": "Der VfGH führt mündliche Verhandlungen durch und entscheidet dann durch einen Mehrheitsbeschluss. Die Entscheidungen des Verfassungsgerichtshofs sind endgültig und bindend."}]'::jsonb, ''),
  ('woin', 'Woin', '', '', '', '', 'Wahlen', '[{"kategorie": "pol.", "text": "\"zentrales demokratisches Instrument in Österreich, das den Bürgerinnen und Bürgern die Möglichkeit gibt, ihre politischen Vertreter auf verschiedenen Ebenen frei und direkt zu bestimmen\""}, {"kategorie": "", "text": "Wahlen sind Ausdruck der [[Volkssouveränität]] und finden auf nationaler, Landes- und Gemeindeebene statt"}, {"kategorie": "", "text": "In Österreich unterliegen Wahlen den Grundsätzen der Allgemeinheit, Freiheit, Gleichheit, Unmittelbarkeit und Geheimhaltung und sind verfassungsrechtlich geschützt"}, {"kategorie": "", "text": "Arten von Wahlen in Österreich: (i) [[Nationalratswahl]]: Die Nationalratswahl findet alle fünf Jahre statt und bestimmt die Abgeordneten des Nationalrats, des wichtigsten Gesetzgebungsorgans auf Bundesebene. Wahlberechtigt sind alle österreichischen [[Staatsbürger]] ab 16 Jahren;  (ii) [[Bundespräsidentenwahl]]: Der Bundespräsident wird direkt vom [[Volk]] für eine Amtszeit von sechs Jahren gewählt. Er ist das Staatsoberhaupt und repräsentiert die Republik Österreich. Eine Wiederwahl ist nur einmal zulässig;  (iii) [[Landtagswahlen]]: In jedem der neun [[Bundesländer]] finden eigene Landtagswahlen statt. Die Bürgerinnen und Bürger wählen die Abgeordneten für ihren Landtag, die dann die [[Landesregierung]] wählen. Die Landtagswahlperiode beträgt je nach Bundesland fünf oder sechs Jahre;  (iv) [[Gemeinderatswahlen]] und Bürgermeisterwahlen: Auf kommunaler Ebene wählen die Bürger die [[Gemeinderäte]]. In manchen Bundesländern wird auch der [[Bürgermeister]] direkt gewählt. Die Wahlperiode beträgt meist fünf oder sechs Jahre, abhängig von den Bestimmungen des jeweiligen Bundeslandes;  (v) [[Europawahlen]]: Bei den Europawahlen wählen die Österreicher ihre Abgeordneten zum Europäischen Parlament. Die Wahl findet alle fünf Jahre statt und ermöglicht den Bürgern, an der politischen Mitgestaltung auf europäischer Ebene teilzuhaben"}, {"kategorie": "", "text": "Wahlen in Österreich sind direkt, das heißt, die Wählerinnen und Wähler wählen ihre Vertreter direkt und nicht über ein Wahlgremium oder durch Zwischeninstanzen. Die Stimmabgabe erfolgt geheim, um den Wählerwillen zu schützen und Manipulationen zu verhindern. Die Wahlkabine und der Wahlakt sind so gestaltet, dass die Entscheidung nicht nachvollzogen werden kann"}, {"kategorie": "", "text": "Wahlrecht und Wahlpflicht: In Österreich gibt es kein verpflichtendes Wahlrecht (Wahlpflicht). Jeder Bürger ist jedoch aufgefordert, an Wahlen teilzunehmen, um die demokratische Legitimation der gewählten Organe zu stärken. Wahlberechtigt sind alle österreichischen Staatsbürger ab 16 Jahren, wobei es je nach Wahl unterschiedliche Regeln für die Kandidatur gibt"}, {"kategorie": "", "text": "Wahlen werden in Österreich von den zuständigen Wahlbehörden organisiert, die auf Bundes-, Landes- und Gemeindeebene tätig sind. Die Durchführung folgt festen Abläufen: (i) [[Wählerverzeichnis]] und Wahlkarten: Vor jeder Wahl wird ein Wählerverzeichnis erstellt, in dem alle wahlberechtigten Personen erfasst sind. Wahlberechtigte, die nicht persönlich zum Wahllokal gehen können, haben die Möglichkeit, eine Wahlkarte für die Briefwahl zu beantragen;  (ii) Die Stimmabgabe erfolgt in Wahllokalen oder per Briefwahl. In den Wahllokalen stehen Wahlkabinen zur Verfügung, die die Geheimhaltung der Wahl sicherstellen;  (iii) Stimmenauszählung und Ergebnisverkündung: Nach Schließung der Wahllokale werden die Stimmen ausgezählt. Das Ergebnis wird zunächst auf lokaler und dann auf nationaler Ebene verkündet. Die Endergebnisse und die Mandatsverteilung werden anschließend offiziell bestätigt"}, {"kategorie": "", "text": "In Österreich überwacht der [[Verfassungsgerichtshof]] (VfGH) die Rechtmäßigkeit der Wahlen. Unregelmäßigkeiten können durch Anfechtungsklagen überprüft werden. Der VfGH kann Wahlen ganz oder teilweise für ungültig erklären, wenn nachweislich Fehler oder Verstöße gegen das Wahlrecht vorlagen, die das Wahlergebnis beeinflusst haben."}]'::jsonb, ''),
  ('woeoelavazeichnis', 'Wöölavazeichnis', '', '', '', '', 'Wählerverzeichnis', '[{"kategorie": "allg.", "text": "\"amtliche Liste in Österreich, die alle wahlberechtigten Bürgerinnen und Bürger eines bestimmten Wahlgebiets erfasst\""}, {"kategorie": "", "text": "Das Wählerverzeichnis dient als Grundlage für die Teilnahme an Wahlen und stellt sicher, dass nur diejenigen Personen ihre Stimme abgeben können, die das [[aktive]] Wahlrecht besitzen"}, {"kategorie": "", "text": "Das Wählerverzeichnis wird vor jeder Wahl erstellt und enthält alle relevanten Informationen, wie Name, Geburtsdatum und Hauptwohnsitz der wahlberechtigten Personen"}, {"kategorie": "", "text": "Durch die Erfassung der wahlberechtigten Personen im Wählerverzeichnis wird sichergestellt, dass jede Person nur einmal wählen kann. So werden Doppelstimmen und Wahlbetrug vermieden"}, {"kategorie": "", "text": "Die Daten für das Wählerverzeichnis werden in Österreich automatisch aus dem [[Melderegister]] der jeweiligen Gemeinden übernommen. Jede wahlberechtigte Person, die einen Hauptwohnsitz in der Gemeinde gemeldet hat, wird in das Wählerverzeichnis eingetragen"}, {"kategorie": "", "text": "Bürger haben das Recht, das Wählerverzeichnis einzusehen und bei Bedarf Berichtigungen zu beantragen, wenn ihre Eintragung fehlerhaft oder unvollständig ist"}, {"kategorie": "", "text": "Ein Wählerverzeichnis enthält üblicherweise folgende Informationen: (i) Name und Geburtsdatum der wahlberechtigten Person, (ii) Adresse des Hauptwohnsitzes, sowie (iii) Kennzeichnung der Personen, die eine [[Wahlkarte]] beantragt haben"}, {"kategorie": "", "text": "Das Wählerverzeichnis stellt sicher, dass alle Bürger, die das Wahlrecht besitzen – also österreichische Staatsbürger ab 16 Jahren, die in Österreich ihren Hauptwohnsitz haben – zur Wahl zugelassen sind. Bei manchen Wahlen, wie der [[Europawahl]] oder [[Gemeinderatswahlen]], sind auch Bürger der EU-Mitgliedstaaten mit Wohnsitz in Österreich wahlberechtigt, sofern sie im Wählerverzeichnis eingetragen sind."}]'::jsonb, ''),
  ('woikoatn', 'Woikoatn', '', '', '', '', 'Wahlkarte', '[{"kategorie": "allg.", "text": "\"Dokument, das wahlberechtigten Personen ermöglicht, ihre Stimme außerhalb ihres zuständigen Wahllokals abzugeben, entweder per [[Briefwahl]] oder in einem beliebigen Wahllokal im Inland oder Ausland\""}, {"kategorie": "", "text": "Die Wahlkarte ist besonders wichtig für Menschen, die am Wahltag nicht an ihrem Wohnort sind, krank sind oder andere Gründe haben, die eine persönliche Stimmabgabe im zuständigen Wahllokal verhindern"}, {"kategorie": "", "text": "Wahlberechtigte müssen die Wahlkarte bei ihrer zuständigen Wohnsitzgemeinde beantragen. Dies kann persönlich, schriftlich, elektronisch (z. B. online über das Portal der jeweiligen Gemeinde) oder in manchen Fällen per Telefon erfolgen"}, {"kategorie": "", "text": "Die Wahlkarte muss innerhalb bestimmter Fristen beantragt werden, die je nach Wahl unterschiedlich sein können. Für eine rechtzeitige Zustellung per Post gibt es eine gesonderte Frist, um sicherzustellen, dass die Stimme rechtzeitig zurückgesandt werden kann"}, {"kategorie": "", "text": "Voraussetzung für die Beantragung einer Wahlkarte ist die Eintragung im Wählerverzeichnis. Nur wer im Wählerverzeichnis erfasst ist, kann eine Wahlkarte erhalten und zur Wahl zugelassen werden"}, {"kategorie": "", "text": "Wahlberechtigte, die sich für die [[Briefwahl]] entscheiden, geben ihre Stimme direkt auf dem Stimmzettel ab, stecken ihn in das vorgesehene Kuvert, das anschließend zusammen mit der unterschriebenen eidesstattlichen Erklärung in die Wahlkarte gelegt wird. Die ausgefüllte Wahlkarte wird dann entweder per Post an die Wahlbehörde zurückgesandt oder bei einer anderen wahlberechtigten Stelle abgegeben"}, {"kategorie": "", "text": "Die Wahlkarte enthält Sicherheitsmerkmale und wird versiegelt, um die Geheimhaltung und Sicherheit der Stimmabgabe zu gewährleisten. Die eidesstattliche Erklärung, die in der Wahlkarte enthalten ist, muss von den Wählern unterschrieben werden, um zu bestätigen, dass sie den Stimmzettel persönlich und unbeeinflusst ausgefüllt haben."}]'::jsonb, ''),
  ('briafwoi', 'Briafwoi', '', '', '', '', 'Briefwahl', '[{"kategorie": "allg.", "text": "\"spezielle Form der Stimmabgabe, die es wahlberechtigten Bürgerinnen und Bürgern ermöglicht, ihre Stimme per Post abzugeben, wenn sie am Wahltag nicht persönlich in ihrem Wahllokal erscheinen können oder möchten\""}, {"kategorie": "", "text": "Die Briefwahl wurde eingeführt, um die Wahlbeteiligung zu fördern und die Teilnahme an Wahlen flexibler zu gestalten, insbesondere für Personen, die sich im Ausland aufhalten, krank sind oder beruflich verhindert sind"}, {"kategorie": "", "text": "Voraussetzung für die Teilnahme an der Briefwahl ist die Beantragung einer [[Wahlkarte]] bei der zuständigen Wohnsitzgemeinde. Die Wahlkarte berechtigt zur Stimmabgabe außerhalb des Wahllokals und dient als Grundlage für die Briefwahl. Sie muss innerhalb festgelegter Fristen beantragt werden, entweder persönlich, schriftlich oder elektronisch (z. B. online). Die Beantragung ist nur für Personen möglich, die im [[Wählerverzeichnis]] eingetragen sind"}, {"kategorie": "", "text": "Nach der Beantragung erhalten Wahlberechtigte die [[Wahlkarte]], die den Stimmzettel und ein Wahlkuvert enthält. Die Wahlkarte enthält außerdem eine eidesstattliche Erklärung, die bestätigt, dass der Stimmzettel persönlich und unbeeinflusst ausgefüllt wurde"}, {"kategorie": "", "text": "Der Wähler füllt den Stimmzettel unbeobachtet und geheim aus, steckt ihn in das Wahlkuvert und verschließt es. Das Kuvert wird dann in die Wahlkarte gelegt, die eidesstattliche Erklärung muss unterschrieben werden, um die Gültigkeit der Briefwahl sicherzustellen"}, {"kategorie": "", "text": "Die ausgefüllte und unterschriebene Wahlkarte wird per Post an die zuständige Wahlbehörde gesandt oder kann persönlich in jedem Wahllokal in Österreich oder bei bestimmten österreichischen Vertretungen im Ausland abgegeben werden. Wichtig ist, dass die Wahlkarte rechtzeitig bei der Wahlbehörde einlangt, um bei der Stimmenauszählung berücksichtigt zu werden."}]'::jsonb, ''),
  ('moeoedegesetz', 'Möödegesetz', '', '', '', '', 'Meldegesetz', '[{"kategorie": "jur.", "text": "\"Gesetz in Österreich, welches die Meldepflicht der Bürgerinnen und Bürger im Zuge der Anmeldung, Abmeldung und Ummeldung ihres Wohnsitzes regelt\""}, {"kategorie": "", "text": "Das Meldegesetz stellt sicher, dass die Meldebehörden über die aktuellen Wohnadressen der in Österreich lebenden Personen informiert sind, und es ist ein wesentlicher Bestandteil im Rahmen der öffentlichen Verwaltung"}, {"kategorie": "", "text": "Das Meldegesetz ist von zentraler Wichtigkeit für die Aktualität des [[Melderegisters]], das für verschiedene Verwaltungszwecke, wie etwa das Erstellen des [[Wählerverzeichnisses]] oder die Zustellung amtlicher Dokumente, genutzt wird"}, {"kategorie": "", "text": "Das Meldegesetz verpflichtet Bürger dazu, ihren Hauptwohnsitz und mögliche Nebenwohnsitze bei den zuständigen Meldebehörden anzumelden. So wird sichergestellt, dass Behörden Kenntnis über die aktuelle Wohnadresse aller in Österreich lebenden Personen haben"}, {"kategorie": "", "text": "Die aktuellen Meldeinformationen sind wichtig für die öffentliche Verwaltung, etwa zur Erstellung von Statistiken, für die Erhebung der Wahlberechtigten und zur Einberufung zum [[Zivildienst]] oder [[Wehrdienst]]. Zudem erleichtert das Meldegesetz den Sicherheitsbehörden die Verfolgung von Personen und trägt zur allgemeinen öffentlichen Sicherheit bei"}, {"kategorie": "", "text": "Personen, die einen neuen Wohnsitz in Österreich beziehen, müssen diesen innerhalb von drei Tagen bei der zuständigen Meldebehörde (z. B. im [[Gemeindeamt]] oder [[Magistrat]]) anmelden. Dies gilt sowohl für den Hauptwohnsitz als auch für eventuelle Nebenwohnsitze"}, {"kategorie": "", "text": "Wird ein Wohnsitz dauerhaft aufgegeben (zum Beispiel bei einem Umzug ins Ausland oder der Aufgabe eines Nebenwohnsitzes), muss die Person sich bei der Meldebehörde abmelden. Dies erfolgt ebenfalls innerhalb von drei Tagen"}, {"kategorie": "", "text": "Bei einem Wechsel des Hauptwohnsitzes ist eine Ummeldung erforderlich. Die alte Meldeadresse wird gelöscht, und die neue Adresse wird im Melderegister eingetragen"}, {"kategorie": "", "text": "Nach der Anmeldung oder Ummeldung erhält die betroffene Person eine Meldebestätigung ([[Meldezettel]]). Dieser kann als Nachweis der Wohnadresse dienen und wird bei vielen amtlichen Anlässen, wie der Beantragung eines Reisepasses oder Führerscheins, benötigt"}, {"kategorie": "", "text": "Das Meldegesetz legt auch Pflichten für Unterkunftgeber (z.B. Vermieter) fest. Diese sind verpflichtet, sicherzustellen, dass ihre Mieter den Wohnsitz melden. In bestimmten Fällen, etwa bei der Aufnahme von Gästen oder bei kurzfristigen Aufenthalten, sind Unterkunftgeber zur Übermittlung der Meldeinformationen verpflichtet"}, {"kategorie": "", "text": "Die Nichteinhaltung der Meldepflichten kann in Österreich zu Verwaltungsstrafen führen. Verstöße gegen das Meldegesetz – etwa das Versäumnis der rechtzeitigen Anmeldung oder Abmeldung – können mit Geldstrafen geahndet werden. Damit sollen die Bürger zur Einhaltung ihrer Meldepflichten angehalten werden, um die Genauigkeit des Melderegisters sicherzustellen."}]'::jsonb, ''),
  ('moeoederegista', 'Mööderegista', '', '', '', '', 'Melderegister', '[{"kategorie": "", "text": "Das Melderegister wird auf Grundlage des österreichischen [[Meldegesetzes]] geführt und dient der Erfassung, Verwaltung und Aktualisierung der Wohnsitze von Bürgerinnen und Bürgern"}, {"kategorie": "", "text": "Das Melderegister enthält Informationen über den [[Hauptwohnsitz]] und mögliche [[Nebenwohnsitze]] sowie über die Zu- und Abmeldungen der Wohnadressen. Es ist ein wesentliches Instrument für die öffentliche [[Verwaltung]] und stellt sicher, dass Behörden über die aktuellen Adressen der Einwohner informiert sind"}, {"kategorie": "", "text": "Durch das Melderegister können Behörden auf aktuelle Informationen zur Wohnadresse zugreifen, was die öffentliche Sicherheit und Ordnung unterstützt, etwa im Rahmen polizeilicher Ermittlungen oder zur schnellen Erreichbarkeit der Bürger in Notfällen"}, {"kategorie": "", "text": "Das Melderegister enthält verschiedene personenbezogene Daten, darunter:  (i) Name, Geburtsdatum und Geschlecht;  (ii) [[Hauptwohnsitz]] und [[Nebenwohnsitze]];  (iii) Staatsangehörigkeit;  (iv) Meldepflichtige Unterkunftgeber (z. B. Vermieter);  (v) Datum der Anmeldung und Abmeldung. Diese Daten werden ausschließlich für amtliche Zwecke genutzt und sind datenschutzrechtlich geschützt"}, {"kategorie": "", "text": "Die [[Gemeindeämter]], [[Magistrate]] und [[Bezirksverwaltungsbehörden]] sind für die Verwaltung des Melderegisters zuständig. Sie nehmen die Anmeldungen, Abmeldungen und Ummeldungen der Bürger entgegen und aktualisieren das Register entsprechend"}, {"kategorie": "", "text": "Nicht alle Behörden haben uneingeschränkten Zugriff auf das Melderegister. Der Zugriff ist auf bestimmte Behörden und staatliche Stellen beschränkt und erfolgt im Rahmen der gesetzlichen Vorgaben. Bürger haben zudem das Recht, Auskunft über die eigenen im Melderegister gespeicherten Daten zu erhalten"}, {"kategorie": "", "text": "Das Melderegister dient zur Erstellung des [[Wählerverzeichnisses]] für [[Wahlen]] und [[Volksabstimmungen]]. Personen, die im Melderegister mit Hauptwohnsitz eingetragen sind, werden automatisch ins Wählerverzeichnis aufgenommen, wenn sie wahlberechtigt sind"}, {"kategorie": "", "text": "Die im Melderegister hinterlegten Adressen werden für die Zustellung von amtlichen Dokumenten und Bescheiden verwendet. So können Bürger sicherstellen, dass sie alle amtlichen Mitteilungen und Verwaltungsentscheidungen erreichen"}, {"kategorie": "", "text": "Jede in Österreich wohnhafte Person ist verpflichtet, ihren Wohnsitz bei der zuständigen Meldebehörde anzumelden. Änderungen, wie ein Umzug oder die Aufgabe eines Wohnsitzes, müssen ebenfalls gemeldet werden. Die Aktualisierung des Melderegisters erfolgt durch die An- und Abmeldung der Wohnsitze und wird von den Meldebehörden verwaltet."}]'::jsonb, ''),
  ('moeoedezeedl', 'Möödezeedl', '', '', '', '', 'Meldezettel', '[{"kategorie": "allg.", "text": "\"amtliches Dokument in Österreich, das zur Anmeldung, Abmeldung oder Ummeldung eines Wohnsitzes bei der zuständigen Meldebehörde verwendet wird\""}, {"kategorie": "", "text": "Mit dem Meldezettel erfüllen Bürgerinnen und Bürger ihre gesetzliche Meldepflicht nach dem österreichischen [[Meldegesetz]] und geben die notwendigen Informationen zu ihrem [[Haupt-]] oder [[Nebenwohnsitz]] an. Der Meldezettel ist erforderlich, um die Wohnsitzdaten im Melderegister zu aktualisieren"}, {"kategorie": "", "text": "Nach erfolgter Anmeldung dient der Meldezettel den [[Bürgern]] als Meldebestätigung, d.h. als offizieller Nachweis der Wohnadresse"}, {"kategorie": "", "text": "Der Meldezettel wird häufig für amtliche Zwecke benötigt, wie etwa bei der Beantragung von Ausweisen, Führerscheinen oder anderen behördlichen Dokumenten"}, {"kategorie": "", "text": "Ein Meldezettel enthält folgende Angaben: (i) Personendaten: Name, Geburtsdatum, Geburtsort, Staatsangehörigkeit und Geschlecht der meldepflichtigen Person;  (ii) Adresse des Wohnsitzes: Hauptwohnsitz oder Nebenwohnsitz, einschließlich Straße, Hausnummer, Postleitzahl und Ort;  (iii) Art des Wohnsitzes: [[Hauptwohnsitz]] oder [[Nebenwohnsitz]];  (iv) Datum des Einzugs oder Auszugs;  (v) Unterschrift des Unterkunftgebers: Der Meldezettel muss in der Regel auch vom Unterkunftgeber (z. B. Vermieter oder Wohnungseigentümer) unterzeichnet werden, um die Richtigkeit der Angaben zu bestätigen"}, {"kategorie": "", "text": "Der Meldezettel muss ausgefüllt sein und bei der zuständigen Meldebehörde, oft dem [[Gemeindeamt]], [[Magistrat]] oder der [[Bezirksverwaltungsbehörde]], eingereicht werden. Die Einreichung erfolgt normalerweise persönlich, kann aber in manchen Fällen auch elektronisch oder postalisch erfolgen"}, {"kategorie": "", "text": "Die Vorlage des Meldezettels muss innerhalb von drei Tagen nach Einzug in die neue Wohnung oder Aufgabe des bisherigen Wohnsitzes erfolgen. Diese Frist dient der Aktualität des Melderegisters"}, {"kategorie": "", "text": "Das österreichische Meldegesetz schreibt die Verwendung des Meldezettels zur Erfüllung der Meldepflicht vor. Jede Person, die einen Wohnsitz in Österreich begründet, aufgibt oder wechselt, ist verpflichtet, dies der Meldebehörde mitzuteilen. Bei Nichteinhaltung der Meldepflicht können Verwaltungsstrafen verhängt werden."}]'::jsonb, ''),
  ('hauptwohnsitz', 'Hauptwohnsitz', '', '', '', '', 'Hauptwohnsitz', '[{"kategorie": "allg.", "text": "\"der zentrale Wohnsitz einer Person in Österreich, an dem sie ihren Lebensmittelpunkt hat und an dem sie die meisten ihrer alltäglichen Lebensbedürfnisse erfüllt\""}, {"kategorie": "", "text": "Der Hauptwohnsitz ist gesetzlich festgelegt und spielt eine wichtige Rolle im österreichischen [[Meldegesetz]], das von allen Bürgern die Anmeldung ihres Hauptwohnsitzes bei der zuständigen Meldebehörde verlangt"}, {"kategorie": "", "text": "Neben dem Hauptwohnsitz können Personen auch [[Nebenwohnsitze]] haben, doch der Hauptwohnsitz ist rechtlich besonders relevant für Fragen des Wahlrechts, Steuerrechts, Sozialleistungen und vieler anderer staatlicher Angelegenheiten"}, {"kategorie": "", "text": "Nach dem österreichischen Meldegesetz ist jede Person verpflichtet, ihren Hauptwohnsitz bei der zuständigen Meldebehörde (z. B. [[Gemeindeamt]] oder [[Magistrat]]) anzumelden. Dies muss in der Regel innerhalb von drei Tagen nach Einzug erfolgen"}, {"kategorie": "", "text": "Eine Person darf in Österreich nur einen Hauptwohnsitz haben, auch wenn sie weitere Nebenwohnsitze besitzt. Die Festlegung des Hauptwohnsitzes ist notwendig, um den eindeutigen Mittelpunkt der Lebensbeziehungen zu bestimmen"}, {"kategorie": "", "text": "Der Hauptwohnsitz bestimmt den Wahlort und das zuständige [[Wählerverzeichnis]], in das die Person eingetragen wird. Nur am Hauptwohnsitz ist man automatisch in das Wählerverzeichnis für nationale und lokale Wahlen eingetragen"}, {"kategorie": "", "text": "Der Hauptwohnsitz hat Auswirkungen auf die steuerliche Veranlagung, da bestimmte Steuervergünstigungen oder Abgaben abhängig vom Hauptwohnsitz gewährt oder erhoben werden können. Auch viele Sozialleistungen, wie das Kinderbetreuungsgeld oder die Wohnbeihilfe, hängen vom Hauptwohnsitz ab"}, {"kategorie": "", "text": "Für schulpflichtige Kinder bestimmt der Hauptwohnsitz, welche Schule im Einzugsgebiet besucht werden soll. Der Wohnort beeinflusst die Einzugsgebiete öffentlicher Schulen und die Berechtigung zur Anmeldung"}, {"kategorie": "", "text": "Fahrzeuganmeldung und Parkberechtigung: Der Hauptwohnsitz ist auch relevant für die Anmeldung von Fahrzeugen und die Berechtigung zur Nutzung von Anwohnerparkzonen in bestimmten Städten.\nÄnderungen und Ummeldung des Hauptwohnsitzes"}, {"kategorie": "", "text": "Das Meldegesetz sieht vor, dass der Hauptwohnsitz korrekt gemeldet wird. Wer dieser Meldepflicht nicht nachkommt oder falsche Angaben macht, kann eine Verwaltungsstrafe erhalten. Die Meldebehörden überprüfen, ob die Angaben den tatsächlichen Lebensverhältnissen entsprechen, insbesondere wenn mehrere Wohnsitze angegeben werden."}]'::jsonb, ''),
  ('nebenwohnsitz', 'Nebenwohnsitz', '', '', '', '', 'Nebenwohnsitz', '[{"kategorie": "allg.", "text": "\"zusätzlicher Wohnsitz einer Person in Österreich, der nicht als [[Hauptwohnsitz]] definiert ist\""}, {"kategorie": "", "text": "Der Nebenwohnsitz ist ein Ort, an dem sich die Person regelmäßig aufhält, aber nicht ihren Lebensmittelpunkt hat"}, {"kategorie": "", "text": "Nebenwohnsitze müssen ebenfalls bei der zuständigen Meldebehörde gemeldet werden, allerdings gelten für sie andere rechtliche Bedingungen als für den Hauptwohnsitz. Typische Nebenwohnsitze sind Ferienwohnungen, Arbeitswohnungen oder Zweitwohnsitze für Wochenendaufenthalte"}, {"kategorie": "", "text": "Anders als beim Hauptwohnsitz, von dem es nur einen geben darf, können Personen mehrere Nebenwohnsitze haben, die ebenfalls gemeldet werden müssen"}, {"kategorie": "", "text": "Im Gegensatz zum Hauptwohnsitz, der als Basis für das [[Wahlrecht]], steuerliche Pflichten und Sozialleistungen dient, hat der Nebenwohnsitz in diesen Bereichen keine vergleichbare Bedeutung. Die meisten Rechte und Pflichten sind an den Hauptwohnsitz gebunden"}, {"kategorie": "", "text": "In einigen Gemeinden oder Städten kann eine Zweitwohnsitzabgabe (auch Nebenwohnsitzabgabe) erhoben werden. Diese Abgabe ist eine Art Steuer, die für den Unterhalt von Nebenwohnsitzen erhoben wird und meist in Tourismusgebieten oder größeren Städten anfällt"}, {"kategorie": "", "text": "Wenn eine Person einen Nebenwohnsitz nicht mehr nutzt oder aufgibt, ist sie verpflichtet, den Nebenwohnsitz bei der Meldebehörde abzumelden. Bei einer Verlegung des Lebensmittelpunkts vom Hauptwohnsitz an einen Nebenwohnsitz muss eine Ummeldung erfolgen, sodass der ehemalige Nebenwohnsitz zum Hauptwohnsitz wird und der ursprüngliche Hauptwohnsitz zum Nebenwohnsitz."}]'::jsonb, ''),
  ('magistrat', 'Magistrat', '', '', '', '', 'Magistrat', '[{"kategorie": "allg.", "text": "\"zentrale Verwaltungsbehörde für die [[Stadt]] Wien, welche für die kommunalen Verwaltungsaufgaben der Bundeshauptstadt zuständig ist\""}, {"kategorie": "", "text": "Da Wien zugleich ein [[Bundesland]] und eine [[Gemeinde]] ist, erfüllt der Magistrat sowohl kommunale als auch landesbehördliche Funktionen"}, {"kategorie": "", "text": "Der Magistrat ist in mehreren Magistratsabteilungen (MA) organisiert, die jeweils für spezifische Aufgabenbereiche zuständig sind, wie etwa Bildung, Verkehr, Gesundheitswesen und Bauwesen"}, {"kategorie": "", "text": "An der Spitze des Wiener Magistrats steht die Magistratsdirektion, die die oberste Verwaltungsbehörde und Leitstelle des Magistrats ist. Die Magistratsdirektion koordiniert die Arbeit der verschiedenen Abteilungen und sorgt für eine effiziente Verwaltung"}, {"kategorie": "", "text": "Der Magistrat ist in über 50 Magistratsabteilungen unterteilt, die jeweils spezifische Aufgabenbereiche abdecken. Beispiele sind:\n(i) MA 35: Einwanderung und Staatsbürgerschaft;  (ii) MA 48: Abfallwirtschaft, Straßenreinigung und Fuhrpark;  (iii) MA 11: Kinder- und Jugendhilfe\nMA 40: Soziales, Sozial- und Gesundheitsrecht"}, {"kategorie": "", "text": "Wien ist in 23 Bezirke unterteilt, und in jedem Bezirk gibt es ein [[Bezirksamt]], das als örtliche Zweigstelle des Magistrats fungiert und bürgernahe Dienstleistungen anbietet. Die Bezirksämter übernehmen unter anderem Aufgaben in den Bereichen Meldewesen, Pass- und Urkundenservice sowie Bauangelegenheiten"}, {"kategorie": "", "text": "Der Magistrat ist für die Erbringung vielfältiger kommunaler Dienstleistungen verantwortlich, etwa im Bereich der Müllentsorgung, Wasserversorgung, Stadtplanung, Verkehrsinfrastruktur und öffentlichen Grünflächen"}, {"kategorie": "", "text": "Der Magistrat Wien ist auch für soziale und gesundheitliche Angelegenheiten zuständig. Dazu gehören Leistungen wie die soziale Unterstützung, Jugendhilfe, Pflegeeinrichtungen, Gesundheitsdienste und die Aufsicht über Krankenhäuser"}, {"kategorie": "", "text": "Aufgaben wie das Meldewesen (An- und Abmeldung des Wohnsitzes), Ausstellung von Ausweisen und Urkunden, Staatsbürgerschafts- und Einwanderungsangelegenheiten fallen ebenfalls in den Aufgabenbereich des Magistrats"}, {"kategorie": "", "text": "Ferner ist der Magistrat auch für Bauangelegenheiten, etwa die Erteilung von Baugenehmigungen, sowie - als Gewerbebehörde - für die Erteilung von [[Gewerbescheinen]] verantwortlich und prüft zudem die Einhaltung von Bau- und Sicherheitsvorschriften"}, {"kategorie": "", "text": "Der Magistrat Wien fördert und organisiert das Bildungswesen in Wien, unterstützt kulturelle Veranstaltungen und Institutionen und verwaltet öffentliche Bildungseinrichtungen und Bibliotheken"}, {"kategorie": "", "text": "Sicherheits- und Ordnungsdienste: Über die Ordnungsdienste, wie etwa die Kontrolle des ruhenden Verkehrs und durch die Unterstützung der Wiener Polizei, trägt der Magistrat zur öffentlichen Sicherheit und Ordnung in Wien bei"}, {"kategorie": "", "text": "Der Magistrat der Stadt Wien bietet Bürgerinnen und Bürgern eine breite Palette an Dienstleistungen, die das tägliche Leben unterstützen und öffentliche Ordnung und Sicherheit gewährleisten. Der Magistrat ist Ansprechpartner für viele administrative Anliegen und erleichtert durch die einzelnen Magistratsabteilungen den Zugang zu öffentlichen Leistungen"}, {"kategorie": "", "text": "Der [[Bürgermeister]] der [[Stadt]] Wien ist gleichzeitig [[Landeshauptmann]] und steht an der Spitze des Magistrats. Der Bürgermeister übt die Aufsicht über den Magistrat aus und ist für die Umsetzung politischer Entscheidungen verantwortlich. Die strategischen Ziele und Prioritäten werden von der [[Stadtregierung]] festgelegt, die Verwaltung des Magistrats setzt diese Ziele operativ um."}]'::jsonb, ''),
  ('gemeindeaumt', 'Gemeindeaumt', '', '', '', '', 'Gemeindeamt', '[{"kategorie": "allg.", "text": "\"Verwaltungsbehörde einer [[Gemeinde]], welche sämtliche kommunalen Verwaltungsaufgaben für die Bürgerinnen und Bürger vor Ort übernimmt\""}, {"kategorie": "", "text": "Das Gemeindeamt ist der zentrale Anlaufpunkt für viele alltägliche Behördenwege und amtliche Angelegenheiten der Einwohner einer Gemeinde"}, {"kategorie": "", "text": "Es wird vom [[Bürgermeister]] geleitet, der die höchste Funktion im Gemeindeamt innehat und für die Verwaltung und Umsetzung kommunaler Aufgaben verantwortlich ist"}, {"kategorie": "", "text": "Das Gemeindeamt ist für das Meldewesen zuständig. Hier können Bürgerinnen und Bürger ihren [[Haupt-]] und [[Nebenwohnsitz]] an-, ab- und ummelden und erhalten Meldebestätigungen"}, {"kategorie": "", "text": "Im Gemeindeamt können amtliche Dokumente wie Geburtsurkunden, Staatsbürgerschaftsnachweise, Meldezettel und Wahlausweise ausgestellt werden"}, {"kategorie": "", "text": "Das Gemeindeamt erstellt und verwaltet das [[Wählerverzeichnis]] und organisiert die Durchführung von Wahlen auf Gemeindeebene, einschließlich der [[Gemeinderatswahlen]], und wirkt an der Organisation nationaler [[Wahlen]] mit"}, {"kategorie": "", "text": "Das Gemeindeamt ist oft Ansprechpartner für soziale Leistungen, wie Familienbeihilfe, Wohnbeihilfe oder Sozialhilfe, und unterstützt Bürger in diesen Bereichen mit Informationen und Anträgen"}, {"kategorie": "", "text": "Das Gemeindeamt übernimmt in kleineren Gemeinden auch die Aufgaben der Bau- und Gewerbebehörde. Es ist zuständig für die Erteilung von Baugenehmigungen, die Aufsicht über Bauvorhaben und die Genehmigung gewerblicher Tätigkeiten"}, {"kategorie": "", "text": "Viele Gemeindeämter führen auch das Standesamt, das für die Beurkundung von Geburten, Eheschließungen und Sterbefällen zuständig ist"}, {"kategorie": "", "text": "Das Gemeindeamt ist oft für die Verwaltung kommunaler Einrichtungen wie Schulen, Kindergärten, Sportstätten und Bibliotheken zuständig. Es organisiert die Instandhaltung und den Betrieb dieser Einrichtungen"}, {"kategorie": "", "text": "Das Gemeindeamt dient als Informationsstelle für die Bürger und bietet Hilfe bei allen Anliegen und Anträgen. Dazu zählen Informationen über kommunale Veranstaltungen, öffentliche Bekanntmachungen und Beratungen in Verwaltungsangelegenheiten"}, {"kategorie": "", "text": "Das Gemeindeamt wird von einem [[Bürgermeister]] geleitet, der die oberste Verantwortung für die kommunalen Aufgaben trägt. Unterstützt wird er in der Regel von einem Gemeindevorstand oder einem [[Gemeinderat]], die gemeinsam die Entscheidungen für die Gemeinde treffen. Die Verwaltungsmitarbeiter im Gemeindeamt kümmern sich um die praktische Umsetzung der Beschlüsse und stehen den Bürgern bei ihren Anliegen zur Seite"}, {"kategorie": "", "text": "Während ein Gemeindeamt für die Verwaltung in kleineren und mittleren Gemeinden zuständig ist, übernehmen in größeren Städten wie Wien die [[Magistrate]] vergleichbare Funktionen, da diese auch landesrechtliche Aufgaben erfüllen. Der Magistrat ist also das Pendant zum Gemeindeamt in Städten mit eigener Stadtverwaltung."}]'::jsonb, ''),
  ('beziaksvawoitungsbehoeade', 'Beziaksvawoitungsbehöade', '', '', '', '', 'Bezirksverwaltungsbehörde', '[{"kategorie": "allg.", "text": "\"staatliche Verwaltungsbehörde auf Bezirksebene, welche eine Vielzahl von Aufgaben im öffentlichen Verwaltungsbereich erfüllt\""}, {"kategorie": "", "text": "Bezirksverwaltungsbehörden übernehmen staatliche Funktionen in jenen Bereichen, in denen keine eigene Stadtverwaltung ([[Magistrat]]) vorhanden ist"}, {"kategorie": "", "text": "Die Bezirksverwaltungsbehörde ist für viele rechtliche Angelegenheiten zuständig, welche die Sicherheit, das Sozialwesen, das Gewerbe- und Bauwesen, das Gesundheitswesen und das Umweltrecht betreffen"}, {"kategorie": "", "text": "In ländlichen Gebieten ist die Bezirksverwaltungsbehörde die [[Bezirkshauptmannschaft]]. In größeren Städten, die zugleich Statutarstädte sind (wie Wien, Graz, Linz und Salzburg), übernimmt das [[Magistrat]] die Funktion der Bezirksverwaltungsbehörde"}, {"kategorie": "", "text": "Die Bezirkshauptmannschaft wird vom [[Bezirkshauptmann]] geleitet, der für die ordnungsgemäße Umsetzung der staatlichen Verwaltungsaufgaben auf Bezirksebene verantwortlich ist. Er wird von der [[Landesregierung]] ernannt und ist direkt an Weisungen der Landesregierung gebunden"}, {"kategorie": "", "text": "Aufgabenbereiche der Bezirksverwaltungsbehörde:  (i) Sicherheit und Ordnung: Die Bezirksverwaltungsbehörde ist für Aufgaben im Bereich der öffentlichen Sicherheit und Ordnung zuständig. Dazu gehören die Ausstellung von Waffenbesitzkarten, Jagd- und Fischereischeinen sowie das Aufgabengebiet der Verkehrsbehörde;  (ii) Gewerbe- und Baurecht: Die Bezirksverwaltungsbehörde fungiert als Gewerbebehörde und ist für die Erteilung von Gewerbegenehmigungen, die Überwachung von Gewerbebetrieben und die Einhaltung von Bauvorschriften zuständig. Sie prüft Bauvorhaben und erteilt Baugenehmigungen im Rahmen des Baugesetzes;  (iii) Sozial- und Gesundheitswesen: Die Bezirksverwaltungsbehörde übernimmt Aufgaben im Sozial- und Gesundheitswesen, darunter Sozialhilfe, Jugendwohlfahrt und das Gesundheitswesen. Sie erteilt Bewilligungen für Gesundheitsberufe und stellt sicher, dass öffentliche Gesundheitsstandards eingehalten werden;  (iv) Umwelt- und Naturschutz: Die Bezirksverwaltungsbehörde ist auch für Umwelt- und Naturschutzangelegenheiten zuständig. Sie genehmigt Projekte im Umweltbereich, wie etwa Rodungen oder Eingriffe in Gewässer, und setzt Naturschutzmaßnahmen um;  (v) Melde- und Personenstandswesen: Die Bezirksverwaltungsbehörde verwaltet das Meldewesen und ist auch für das Personenstandswesen (z. B. Geburten, Eheschließungen, Sterbefälle) zuständig, sofern keine Gemeinde diese Aufgabe übernimmt;  (vi) Straßenverkehrsbehörde: Sie ist für straßenpolizeiliche Angelegenheiten wie die Erteilung von Führerscheinen, die Zulassung von Fahrzeugen und die Regelung des Verkehrs im Bezirk zuständig"}, {"kategorie": "", "text": "Während das Gemeindeamt kommunale Angelegenheiten der [[Gemeinde]] regelt, handelt die Bezirksverwaltungsbehörde als staatliche Verwaltungsstelle auf Bezirksebene und ist für Aufgaben verantwortlich, die über den Rahmen der [[Gemeindeverwaltung]] hinausgehen. In Gemeinden ohne eigenes Stadt- oder Bezirksamt übernimmt die Bezirksverwaltungsbehörde oft auch Aufgaben des [[Gemeindeamts]]."}]'::jsonb, ''),
  ('gemeinde', 'Gemeinde', '', '', '', '', 'Gemeinde', '[{"kategorie": "allg.", "text": "\"kleinste Verwaltungseinheit des Staates, welche Aufgaben der lokalen Selbstverwaltung übernimmt\""}, {"kategorie": "", "text": "Die Gemeinde ist eine rechtlich eigenständige [[Körperschaft]] des öffentlichen Rechts und erfüllt vielfältige administrative und infrastrukturelle Aufgaben für ihre Bürgerinnen und Bürger"}, {"kategorie": "", "text": "In Österreich gibt es knapp 2.100 Gemeinden, die jeweils über eigene Verwaltungsstrukturen, meist in Form eines [[Gemeindeamts]] und eines [[Gemeinderats]], verfügen"}, {"kategorie": "", "text": "Die rechtliche Grundlage für die Gemeindeorganisation und ihre Aufgaben bildet die [[österreichische]] Bundesverfassung sowie die jeweiligen Gemeindeordnungen der Bundesländer"}, {"kategorie": "", "text": "Gemeinden haben ein verfassungsrechtlich gesichertes [[Selbstverwaltungsrecht]]. Das bedeutet, dass sie in bestimmten Bereichen eigenständig und unabhängig von staatlicher Kontrolle handeln dürfen. Zu diesen Aufgaben gehören etwa die Verwaltung von Gemeindeeigentum, örtliche Bauangelegenheiten, kommunale Infrastruktur und die Bereitstellung von Bildungs- und Sozialdiensten"}, {"kategorie": "", "text": "Als [[Gebietskörperschaft]] ist die Gemeinde rechtlich eigenständig und besitzt das Recht, über eigene Mittel zu verfügen, Steuern zu erheben (z. B. Kommunalsteuer) und Personal einzustellen. Sie handelt im Interesse ihrer Einwohner und verwaltet ihr Gebiet unter Berücksichtigung der gesetzlichen Vorgaben"}, {"kategorie": "", "text": "Die Gemeinde hat eine Doppelfunktion: Zum einen erfüllt sie Aufgaben der eigenen [[Selbstverwaltung]] (z. B. Bauwesen, Müllentsorgung), zum anderen agiert sie als staatliche Behörde im Auftrag des [[Bundes]] oder des [[Landes]], zum Beispiel bei der Durchführung von [[Wahlen]] und Meldeangelegenheiten"}, {"kategorie": "", "text": "Der [[Gemeinderat]] ist das höchste Gremium der Gemeinde und wird von den Bürgerinnen und Bürgern in allgemeinen Wahlen gewählt. Der Gemeinderat ist für die Beschlussfassung in allen wesentlichen Angelegenheiten der Gemeinde zuständig, wie etwa dem Budget, der Gemeindepolitik und den lokalen Verordnungen"}, {"kategorie": "", "text": "Der [[Bürgermeister]] ist das Oberhaupt der Gemeinde und leitet die [[Gemeindeverwaltung]]. Er wird entweder direkt von den Bürgern oder vom Gemeinderat gewählt und ist verantwortlich für die Umsetzung der Beschlüsse des Gemeinderats sowie die ordnungsgemäße Verwaltung der Gemeinde"}, {"kategorie": "", "text": "Das [[Gemeindeamt]] ist die Verwaltungsstelle der Gemeinde, in der die alltäglichen Verwaltungsaufgaben und Bürgeranliegen abgewickelt werden. Hier finden Bürger Unterstützung in Belangen wie Meldewesen, Bauangelegenheiten und Sozialhilfe"}, {"kategorie": "", "text": "Gemeinden sind für die Bereitstellung der Infrastruktur zuständig, darunter die Instandhaltung von Straßen, Wasser- und Abwasserversorgung, Müllentsorgung und öffentlicher Nahverkehr. Diese Aufgaben sind Teil der kommunalen Daseinsvorsorge, die das tägliche Leben der Bürger erleichtert"}, {"kategorie": "", "text": "Die Gemeinde ist für den Bau und die Erhaltung von Schulen, Kindergärten und Freizeiteinrichtungen zuständig. Sie unterstützt soziale Dienste, darunter Jugendbetreuung, Altenhilfe und Sozialhilfe, und sorgt so für die sozialen Bedürfnisse der Einwohner"}, {"kategorie": "", "text": "Im Gemeindeamt können Bürgerinnen und Bürger ihren Wohnsitz an-, ab- oder ummelden und wichtige Dokumente wie Geburtsurkunden, Staatsbürgerschaftsnachweise und Meldebestätigungen erhalten"}, {"kategorie": "", "text": "Die Gemeinde übernimmt die örtliche Bauaufsicht und ist zuständig für die Erteilung von Baugenehmigungen sowie die Einhaltung der Bauvorschriften. Zudem regelt sie die Raumordnung und Stadtplanung, um eine sinnvolle und nachhaltige Entwicklung des Gemeindegebiets zu fördern"}, {"kategorie": "", "text": "Gemeinden fördern die Kultur und organisieren kulturelle Veranstaltungen, Freizeitmöglichkeiten und Sportangebote für die Bevölkerung. Sie unterstützen oft Vereine und kulturelle Initiativen, die zur Gemeinschaft und Lebensqualität beitragen"}, {"kategorie": "", "text": "Es gibt verschiedene Gemeindetypen in Österreich:  (i) Ortsgemeinde: Die typische Form der Gemeinde in Österreich;  (ii) Marktgemeinde: Eine Gemeinde mit traditioneller Marktberechtigung und oft historischer Bedeutung;  (iii) Stadtgemeinde: Eine Gemeinde mit Stadtrecht, das besondere Privilegien und Verwaltungsrechte umfasst;  (iv) Statutarstadt: Städte wie Graz, Linz oder Salzburg, die zugleich Gemeinde und Bezirksverwaltungsbehörde sind und daher keine eigene [[Bezirkshauptmannschaft]] haben."}]'::jsonb, ''),
  ('beziaksaumt', 'Beziaksaumt', '', '', '', '', 'Bezirksamt', '[{"kategorie": "allg.", "text": "\"Verwaltungsbehörde eines Bezirks\""}, {"kategorie": "", "text": "Ein Bezirksamt ist verantwortlich für die örtliche Vollziehung von Gesetzen und übernimmt Verwaltungsaufgaben im Namen des [[Bundes]] oder des jeweiligen [[Bundeslandes]]"}, {"kategorie": "", "text": "Es ist eine zentrale Behörde auf Bezirksebene und erfüllt verschiedene Funktionen, die nicht nur die öffentliche Sicherheit und Ordnung betreffen, sondern auch Bereiche wie Gewerbewesen, Sozialwesen, Baurecht und Gesundheitswesen"}, {"kategorie": "", "text": "Typische Aufgaben des Bezirksamts in Österreich sind:  (i) Verwaltungsaufgaben: Ausstellung von Genehmigungen (z. B. Gewerbescheine, Baubewilligungen);  (ii) Soziale Angelegenheiten: Unterstützung bei Sozialleistungen oder sozialrechtlichen Anträgen;  (iii) Öffentliche Sicherheit: Polizeiangelegenheiten und Sicherheitsverwaltungsaufgaben;  (iv) Gesundheits- und Veterinärwesen: Gesundheitsüberwachung, Hygieneinspektionen, Veterinärkontrollen;  (v) Wahlabwicklung: Organisation und Durchführung von Wahlen auf Bezirksebene"}, {"kategorie": "", "text": "In manchen Regionen wird das Bezirksamt auch als [[Bezirkshauptmannschaft]] bezeichnet, insbesondere in den meisten Bundesländern außer in Wien, wo man den Begriff [[Magistratisches Bezirksamt]] verwendet."}]'::jsonb, ''),
  ('magistratsdirektion', 'Magistratsdirektion', '', '', '', '', 'Magistratsdirektion', '[{"kategorie": "allg.", "text": "\"zentrales Verwaltungsorgan der [[Stadt]] Wien, welches die Arbeit der verschiedenen [[Magistratsabteilungen]] und Dienststellen koordiniert\""}, {"kategorie": "", "text": "Die Magistratsdirektion fungiert als die oberste Leitungs- und Koordinationsstelle innerhalb der [[Wiener]] Stadtverwaltung und ist direkt dem [[Bürgermeister]] unterstellt"}, {"kategorie": "", "text": "Die Magistratsdirektion unterstützt die politischen Organe der Stadt bei der Umsetzung ihrer Entscheidungen und stellt sicher, dass die Verwaltungsaufgaben effizient und ordnungsgemäß ausgeführt werden"}, {"kategorie": "", "text": "Hauptaufgaben der Wiener Magistratsdirektion:  (i) Koordination und Leitung: Sie sorgt für die reibungslose Zusammenarbeit zwischen den einzelnen Magistratsabteilungen und den Magistratischen Bezirksämtern. Die Magistratsdirektion stellt sicher, dass die Abläufe einheitlich und effizient gestaltet sind;  (ii) Beratung und Unterstützung: Die Magistratsdirektion unterstützt den Bürgermeister, den [[Stadtsenat]] und die politischen Gremien der Stadt Wien in administrativen Angelegenheiten. Sie berät diese in rechtlichen, strategischen und operativen Fragen;  (iii) Strategische Planung und Steuerung: Die Magistratsdirektion entwickelt und überwacht die strategische Planung der Stadtverwaltung, legt langfristige Ziele fest und sorgt für deren Umsetzung. Dies umfasst auch die Stadtentwicklungsplanung, die Personalplanung und die Finanzsteuerung;  (iv) Controlling und Qualitätsmanagement: Sie stellt sicher, dass die Qualität der städtischen Dienstleistungen und Projekte den festgelegten Standards entspricht. Durch ein umfassendes Controlling überwacht die Magistratsdirektion die Effizienz und Effektivität der städtischen Verwaltungsarbeit;  (v) Personalmanagement: Die Magistratsdirektion ist verantwortlich für das zentrale Personalwesen der Stadt Wien, einschließlich Personalplanung, Ausbildung und Personalentwicklung für alle städtischen Bediensteten;  (vi) Kommunikation und Öffentlichkeitsarbeit: Sie koordiniert die Kommunikationsstrategien der Stadt Wien und sorgt für den transparenten Informationsfluss gegenüber der Öffentlichkeit;  (vii) IT und Digitalisierung: Die Magistratsdirektion spielt eine Schlüsselrolle bei der Digitalisierung der Wiener Stadtverwaltung und entwickelt die IT-Infrastruktur weiter, um die digitalen Services für Bürgerinnen und Mitarbeiterinnen zu verbessern"}, {"kategorie": "", "text": "Die Magistratsdirektion gliedert sich in verschiedene Geschäftsgruppen, die jeweils spezifische Verwaltungsbereiche abdecken, darunter Personal, Finanzen, strategische Planung und Controlling, Rechtsangelegenheiten und Kommunikation. Jede Geschäftsgruppe wird von einem Geschäftsgruppenleiter geführt, und die Gesamtheit der Abteilungen wird vom Magistratsdirektor geleitet, der als höchste Verwaltungsposition in der Wiener Stadtverwaltung fungiert"}, {"kategorie": "", "text": "Die Wiener Magistratsdirektion bildet somit das organisatorische Rückgrat der Stadtverwaltung und sorgt dafür, dass die politischen und administrativen Prozesse effizient und im Einklang mit den gesetzlichen Vorgaben ablaufen."}]'::jsonb, ''),
  ('magistratsobtaeulungan', 'Magistratsobtäulungan', '', '', '', '', 'Magistratsabteilungen', '[{"kategorie": "", "text": "Jede Magistratsabteilung ist für bestimmte Aufgaben- und Fachbereiche zuständig und übernimmt administrative und operative Funktionen, um die städtischen Dienstleistungen für die Bürger*innen sicherzustellen. Diese Struktur ermöglicht eine klare Aufgabenverteilung und eine effiziente Verwaltung in den vielfältigen Bereichen des öffentlichen Lebens in Wien"}, {"kategorie": "", "text": "Die Magistratsabteilungen sind nummeriert und thematisch gegliedert, wobei jede Abteilung einen spezifischen Zuständigkeitsbereich abdeckt. Zu den bekanntesten Magistratsabteilungen gehören zum Beispiel:  (i) MA 01 – Wiener Digitales: Verantwortlich für die Digitalisierung der Stadt und die Entwicklung von IT-Infrastrukturen;  (ii) MA 13 – Bildung und Jugend: Zuständig für Bildungsangebote, Kinderbetreuungseinrichtungen und Jugendprogramme;  (iii) MA 15 – Gesundheitsdienst der Stadt Wien: Übernimmt Aufgaben im öffentlichen Gesundheitswesen, wie Gesundheitsprävention, Hygienekontrollen und medizinische Betreuung;  (iv) MA 18 – Stadtentwicklung und Stadtplanung: Plant die bauliche und infrastrukturelle Entwicklung der Stadt und entwirft Strategien für nachhaltiges Wachstum;  (v) MA 48 – Abfallwirtschaft, Straßenreinigung und Fuhrpark: Verwaltet die städtische Abfallentsorgung, Straßenreinigung und den Fuhrpark der Stadt"}, {"kategorie": "", "text": "Hauptaufgaben der Magistratsabteilungen:  (i) Umsetzung von Gesetzen und Verordnungen: Jede Abteilung ist für die Umsetzung und Überwachung der Einhaltung städtischer und landesweiter Gesetze sowie Verordnungen in ihrem jeweiligen Fachgebiet verantwortlich;  (ii) Service und Dienstleistungen für Bürger*innen: Die Magistratsabteilungen bieten zahlreiche Dienstleistungen an, wie z. B. Anträge für Baubewilligungen, soziale Unterstützung, Gesundheitsberatung, Wohnservices und Umweltberatung;  (iii) Stadtentwicklung und Infrastruktur: Abteilungen wie die MA 18 und MA 28 (Straßenverwaltung und Straßenbau) tragen zur Planung und Entwicklung der städtischen Infrastruktur bei und fördern die nachhaltige Stadtentwicklung;  (iv) Gesundheit und Soziales: Abteilungen wie die MA 15 und MA 40 (Soziales, Sozial- und Gesundheitsrecht) kümmern sich um die öffentliche Gesundheit, soziale Unterstützung und betreuen soziale Einrichtungen und Gesundheitsdienste;  (v) Umwelt und Sicherheit: Abteilungen wie die MA 22 (Umweltschutz) arbeiten an Maßnahmen für Umweltschutz, Nachhaltigkeit und Sicherheitsvorkehrungen in Wien;  (vi) Kultur und Bildung: Die MA 7 (Kultur) und MA 13 fördern kulturelle Aktivitäten, organisieren Veranstaltungen und unterstützen Bildungsprogramme für verschiedene Altersgruppen"}, {"kategorie": "", "text": "Rolle der Magistratsabteilungen in der Wiener Stadtverwaltung: Die Wiener Magistratsabteilungen ermöglichen eine dezentralisierte und effiziente Verwaltung, die sich gezielt um verschiedene Aufgabenbereiche kümmert und dadurch die Qualität und Erreichbarkeit der städtischen Dienstleistungen gewährleistet. Jede Abteilung hat eigene Anlaufstellen für Bürger*innen und stellt Ressourcen zur Verfügung, die auf die spezifischen Bedürfnisse der Bevölkerung und der Stadtstruktur abgestimmt sind."}]'::jsonb, ''),
  ('gebiitskoeapaschoft', 'Gebiitsköapaschoft', '', '', '', '', 'Gebietskörperschaft', '[{"kategorie": "allg.", "text": "\"juristische Person des öffentlichen Rechts, die für die Verwaltung eines geografisch abgegrenzten Gebietes zuständig ist\""}, {"kategorie": "", "text": "Gebietskörperschaften besitzen eine rechtlich festgelegte Autonomie und können eigenverantwortlich bestimmte Verwaltungsaufgaben für ihre jeweilige Region erfüllen. Sie haben das Recht, [[Gesetze]] und [[Verordnungen]] zu erlassen sowie Abgaben und Steuern zu erheben"}, {"kategorie": "", "text": "Arten von Gebietskörperschaften in Österreich:  (i) Der [[Bund]]: Die Bundesrepublik Österreich ist die höchste Gebietskörperschaft und zuständig für alle Aufgaben, die auf nationaler Ebene geregelt werden, wie Außenpolitik, Verteidigung und Justiz. Der Bund kann Gesetze für das gesamte Staatsgebiet erlassen und verwaltet zentrale Institutionen und öffentliche Dienste;  (ii) Die [[Bundesländer]]: Österreich ist in neun Bundesländer gegliedert, die jeweils ihre eigenen Gebietskörperschaften darstellen. Jedes Bundesland hat eine eigene Landesverfassung, einen [[Landtag]] (als gesetzgebendes Organ) und eine [[Landesregierung]], die bestimmte Angelegenheiten eigenständig regelt, etwa in den Bereichen Bildung, Kultur, Naturschutz und Bauwesen;  (iii) Die [[Gemeinden]]: Die Gemeinden sind die kleinste Einheit der Gebietskörperschaften und zuständig für lokale Aufgaben wie Abfallwirtschaft, Wasserversorgung, Bauwesen und Verwaltung von Schulen. Jede Gemeinde hat eine Gemeindevertretung und einen [[Bürgermeister]], die gemeinsam die Gemeindeautonomie wahrnehmen"}, {"kategorie": "", "text": "Merkmale von Gebietskörperschaften:  (i) Rechtliche Selbstständigkeit: Jede Gebietskörperschaft hat eine eigenständige Rechtsposition und kann eigenverantwortlich Entscheidungen treffen;  (ii) Autonomiebereich: Die Gebietskörperschaften verfügen über einen bestimmten autonomen Handlungsspielraum, der durch Bundes- oder Landesgesetze definiert ist;  (iii) Steuer- und Abgabenrecht: Gebietskörperschaften können innerhalb ihres Zuständigkeitsbereiches Steuern, Gebühren und Abgaben erheben, um ihre Aufgaben zu finanzieren;  (iv) Wahlrecht und politische Vertretung: Die Organe der Gebietskörperschaften (z. B. [[Nationalrat]] für den [[Bund]], [[Landtage]] für die [[Bundesländer]] und [[Gemeinderäte]] für die [[Gemeinden]]) werden durch Wahlen bestimmt"}, {"kategorie": "", "text": "Aufgaben von Gebietskörperschaften:  (i) Die Aufgabenverteilung zwischen den Gebietskörperschaften in Österreich ist durch das Prinzip der Subsidiarität geprägt. Das bedeutet, dass Aufgaben möglichst von der kleinsten zuständigen Gebietskörperschaft übernommen werden sollen. So ist der Bund für überregionale und internationale Aufgaben zuständig, die Bundesländer für landesspezifische und die Gemeinden für lokale Belange."}]'::jsonb, ''),
  ('soebstvawoitung', 'Söbstvawoitung', '', '', '', '', 'Selbstverwaltung', '[{"kategorie": "allg.", "text": "\"Prinzip, dass bestimmte öffentliche Aufgaben von eigenständigen Körperschaften eigenverantwortlich wahrgenommen werden, ohne direkte Weisungen des Staates\""}, {"kategorie": "", "text": "Selbstverwaltung bedeutet, dass [[Körperschaften]] und Institutionen mit bestimmten Aufgaben betraut werden und in diesen Bereichen Entscheidungsbefugnisse und organisatorische Autonomie haben, auch wenn sie letztlich dem öffentlichen Interesse und der staatlichen Aufsicht unterstehen"}, {"kategorie": "", "text": "In Österreich gibt es verschiedene Formen der Selbstverwaltung, die vor allem auf Gemeinde-, beruflicher und sozialer Ebene zum Einsatz kommen. Das Konzept der Selbstverwaltung ist ein wichtiges Element der föderalen und demokratischen Struktur des Landes"}, {"kategorie": "", "text": "Formen der Selbstverwaltung in Österreich:  (i) Territoriale Selbstverwaltung: Bezieht sich auf die Selbstverwaltung der [[Gemeinden]] und [[Städte]]. Gemeinden übernehmen kommunale Aufgaben und treffen Entscheidungen in Bereichen wie örtliche Raumplanung, Wasserversorgung, Abfallentsorgung und Bauordnung eigenständig. Sie besitzen hierfür eine gewählte [[Gemeindeverwaltung]] ([[Gemeinderat]] und [[Bürgermeister]]) und haben eigene Budgets. Der Staat hat nur eine Aufsichtsfunktion und greift nur in besonderen Fällen ein;  (ii) Berufsständische Selbstverwaltung: Berufskammern und Standesvertretungen, wie z. B. die [[Wirtschaftskammer]], die Ärztekammer oder die [[Arbeiterkammer]], haben die Aufgabe, die Interessen ihrer Mitglieder zu vertreten, berufsständische Regelungen festzulegen und teils auch Prüfungen und Qualifikationen zu überwachen. Die Mitgliedschaft ist oft verpflichtend, und die Kammern agieren autonom in ihrer Verwaltung und im Umgang mit ihren Mitgliedern, sind jedoch an gesetzliche Vorgaben und staatliche Aufsicht gebunden;  (iii) Soziale Selbstverwaltung: Die [[Sozialversicherungsträger]] (z. B. die [[Österreichische]] Gesundheitskasse und die [[Pensionsversicherungsanstalt]]) verwalten das Sozialversicherungssystem in Österreich. Sie sind [[Körperschaften]] öffentlichen Rechts und haben die Aufgabe, die Beiträge zu erheben und Leistungen auszuzahlen. Dabei entscheiden sie weitgehend eigenverantwortlich über die Verwaltung der Mittel und die Organisation der sozialen Absicherung"}, {"kategorie": "", "text": "Autonomie: Selbstverwaltungskörperschaften haben in ihrem Aufgabenbereich das Recht, Entscheidungen selbstständig zu treffen und Satzungen oder Ordnungen zu erlassen"}, {"kategorie": "", "text": "Die Leitung und Vertretung dieser Körperschaften erfolgt durch gewählte Organe (z.B. [[Gemeinderäte]] oder Kammerpräsidenten), die demokratisch legitimiert sind"}, {"kategorie": "", "text": "Staatliche Aufsicht: Auch wenn Selbstverwaltungskörperschaften autonom agieren, unterliegen sie der staatlichen Aufsicht (meist durch die [[Landesregierung]] oder [[Ministerien]]), die sicherstellt, dass die Aufgaben ordnungsgemäß und gesetzeskonform erfüllt werden"}, {"kategorie": "", "text": "Finanzielle Eigenverantwortung: Die Körperschaften verwalten eigene Budgets und finanzieren sich oft durch Beiträge ihrer Mitglieder (z. B. Kammerbeiträge) oder durch kommunale Steuern und Abgaben"}, {"kategorie": "", "text": "Die Selbstverwaltung ist somit ein wichtiger Pfeiler des österreichischen Verwaltungssystems und stärkt sowohl die föderale Struktur als auch die Bürgerbeteiligung im öffentlichen Leben."}]'::jsonb, ''),
  ('statutarschdodt', 'Statutarschdodt', '', '', '', '', 'Statutarstadt', '[{"kategorie": "allg.", "text": "\"[[Stadtgemeinde]] in Österreich, die durch ein eigenes Stadtrecht (Statut) zusätzliche Verwaltungsbefugnisse besitzt und die Aufgaben einer [[Bezirkshauptmannschaft]] übernimmt\""}, {"kategorie": "", "text": "Statutarstädte verwalten sich daher nicht nur als [[Gemeinde]], sondern auch als eigener politischer Bezirk, wodurch sie eine größere Autonomie und Verantwortung in der Verwaltung haben"}, {"kategorie": "", "text": "Merkmale einer Statutarstadt:  (i) Eigene Verwaltungsstrukturen: Die Statutarstadt führt sowohl kommunale Aufgaben als auch Aufgaben der Bezirksverwaltung durch;  (ii) Stadtrecht (Statut): Jede Statutarstadt hat ein eigenes Stadtrecht, das in einem speziellen Statut festgelegt ist und ihr besondere Selbstverwaltungsrechte verleiht;  (iii) Rechtliche Grundlage: Statutarstädte werden durch Landesgesetze als solche definiert und erhalten ihre Rechte durch das jeweilige Stadtrecht"}, {"kategorie": "", "text": "Beispiele für Statutarstädte in Österreich: Zu den 15 Statutarstädten zählen unter anderem Wien, Graz, Linz, Salzburg, Innsbruck und Klagenfurt"}, {"kategorie": "", "text": "Die Sonderstellung der Statutarstädte ermöglicht eine effizientere Verwaltung durch die Bündelung von Gemeinde- und Bezirksaufgaben in einer Behörde."}]'::jsonb, ''),
  ('moakdgemeinde', 'Moakdgemeinde', '', '', '', '', 'Marktgemeinde', '[{"kategorie": "allg.", "text": "\"Gemeinde in Österreich, welcher aufgrund ihrer historischen oder wirtschaftlichen Bedeutung das Recht verliehen wurde, den Titel „Marktgemeinde“ zu führen\""}, {"kategorie": "", "text": "Traditionell hatten Marktgemeinden das Privileg, regelmäßige Märkte abzuhalten, was ihnen eine besondere wirtschaftliche und soziale Stellung im Vergleich zu anderen Gemeinden verschaffte"}, {"kategorie": "", "text": "Heute hat der Status einer Marktgemeinde vor allem repräsentativen Charakter und symbolisiert die historische Bedeutung des Ortes"}, {"kategorie": "", "text": "Merkmale einer Marktgemeinde:  (i) Historische Bedeutung: Marktgemeinden haben häufig eine lange Geschichte und spielten in der regionalen Wirtschaft eine wichtige Rolle;  (ii) Titelverleihung: Der Status als Marktgemeinde wird durch ein Landesgesetz oder einen behördlichen Akt verliehen und ist an keine speziellen zusätzlichen Rechte oder Pflichten gebunden;  (iii) Repräsentativer Charakter: Der Titel hat heute in erster Linie einen symbolischen Wert und soll die historische Bedeutung und das kulturelle Erbe der Gemeinde hervorheben"}, {"kategorie": "", "text": "Beispiele für Marktgemeinden: Zu den Marktgemeinden in Österreich gehören Orte wie Gloggnitz, St. Wolfgang und Lustenau"}, {"kategorie": "", "text": "Marktgemeinden sind damit ein wichtiges Element der österreichischen Gemeindelandschaft und tragen zur kulturellen Identität und historischen Vielfalt des Landes bei."}]'::jsonb, ''),
  ('schdodtgemeinde', 'Schdodtgemeinde', '', '', '', '', 'Stadtgemeide', '[{"kategorie": "allg.", "text": "\"[[Gemeinde]] in Österreich, die aufgrund ihrer Einwohnerzahl, Infrastruktur oder historischen Bedeutung den Status einer [[Stadt]] besitzt\""}, {"kategorie": "", "text": "Dieser Status wird in der Regel durch ein Landesgesetz verliehen und ist in erster Linie repräsentativ, da Stadtgemeinden keine besonderen Verwaltungsrechte oder Pflichten haben, die sie von anderen Gemeinden unterscheiden"}, {"kategorie": "", "text": "Stadtgemeinden übernehmen dieselben kommunalen Aufgaben wie andere [[Gemeinden]], wobei größere Städte oft zusätzliche Verwaltungsstrukturen benötigen"}, {"kategorie": "", "text": "Merkmale einer Stadtgemeinde:  (i) Verleihung des Stadtstatus: Der Status als Stadtgemeinde wird durch das jeweilige [[Bundesland]] verliehen und hängt meist von Kriterien wie der Einwohnerzahl, wirtschaftlichen Bedeutung oder historischen Relevanz ab;  (ii) Kommunale Aufgaben: Stadtgemeinden erfüllen die gleichen Aufgaben wie andere Gemeinden, darunter Infrastruktur, Bildung, Kultur und Verwaltung, oft jedoch in größerem Umfang;  (iii) Repräsentative Bedeutung: Der Stadtstatus ist vor allem symbolisch und hebt die Bedeutung und Größe der Gemeinde hervor, ohne dass damit automatisch zusätzliche rechtliche Kompetenzen verbunden sind"}, {"kategorie": "", "text": "Beispiele für Stadtgemeinden: In Österreich gibt es zahlreiche Stadtgemeinden, von kleineren Städten wie Oberndorf bei Salzburg bis zu größeren Städten wie Wiener Neustadt oder Villach"}, {"kategorie": "", "text": "Stadtgemeinden tragen somit zur administrativen und kulturellen Vielfalt des Landes bei und sind wichtige Zentren für die regionale Wirtschaft und das öffentliche Leben."}]'::jsonb, ''),
  ('schdodt', 'Schdodt', '', '', '', '', 'Stadt', '[{"kategorie": "allg.", "text": "\"Gemeinde in Österreich, die aufgrund ihrer Größe, wirtschaftlichen Bedeutung oder historischen Relevanz den Titel „Stadt“ erhalten hat\""}, {"kategorie": "", "text": "Dieser Titel wird durch das jeweilige [[Bundesland]] verliehen und dient hauptsächlich der Anerkennung des urbanen Charakters einer Gemeinde"}, {"kategorie": "", "text": "Städte erfüllen dabei die gleichen kommunalen Aufgaben wie andere [[Gemeinden]], verfügen jedoch häufig über eine umfangreichere Infrastruktur und spielen eine zentrale Rolle in der regionalen Wirtschaft, Kultur und Verwaltung"}, {"kategorie": "", "text": "Merkmale einer Stadt in Österreich:  (i) Verleihung des Titels: Der Status als Stadt wird durch einen offiziellen Beschluss des Bundeslandes verliehen, oft basierend auf Kriterien wie Einwohnerzahl, wirtschaftlicher Bedeutung oder historischer Funktion;  (ii) Funktionale Bedeutung: Städte haben häufig eine zentrale Bedeutung für die umliegenden Regionen und sind Standorte wichtiger Einrichtungen wie Schulen, Krankenhäuser, kultureller Einrichtungen und Wirtschaftszentren;  (iii) Symbolische Anerkennung: Der Titel „Stadt“ hat primär repräsentativen Charakter und unterstreicht die urbane und kulturelle Bedeutung der Gemeinde"}, {"kategorie": "", "text": "Arten von Städten:  (i) [[Stadtgemeinde]]: Städte, die formal als Gemeinden verwaltet werden;  (ii) [[Statutarstadt]]: Städte mit besonderem Verwaltungsstatus, die gleichzeitig als politischer Bezirk fungieren und erweiterte Verwaltungsbefugnisse haben (z. B. Wien, Graz, Linz)"}, {"kategorie": "", "text": "Städte in Österreich sind somit wichtige Zentren des öffentlichen Lebens und tragen wesentlich zur wirtschaftlichen und kulturellen Entwicklung ihrer Regionen bei."}]'::jsonb, ''),
  ('soebstvawoitungsrecht', 'Söbstvawoitungsrecht', '', '', '', '', 'Selbstverwaltungsrecht', '[{"kategorie": "allg.", "text": "\"das verfassungsrechtlich verankerte Recht bestimmter [[Körperschaften]] in Österreich, ihre Aufgaben eigenständig und unabhängig vom direkten staatlichen Einfluss zu erfüllen\""}, {"kategorie": "", "text": "Dieses Prinzip gilt insbesondere für [[Gemeinden]], aber auch für andere [[Körperschaften]] öffentlichen Rechts, wie [[Berufs-]] und [[Standesvertretungen]] (z. B. [[Kammern]]) und [[Sozialversicherungsträger]]. Das Selbstverwaltungsrecht ermöglicht es diesen Körperschaften, ihre Angelegenheiten autonom zu regeln und eigene Satzungen oder Verordnungen zu erlassen, wobei sie lediglich der Aufsicht des [[Staates]] unterliegen, der die Einhaltung der Gesetze sicherstellt"}, {"kategorie": "", "text": "Merkmale des Selbstverwaltungsrechts in Österreich:  (i) Verfassungsrechtliche Grundlage: Das Selbstverwaltungsrecht ist in der [[österreichischen]] Bundesverfassung verankert und garantiert den betroffenen Körperschaften ihre Unabhängigkeit in bestimmten Verwaltungsbereichen;  (ii) Eigenverantwortliche Aufgabenerfüllung: Körperschaften mit Selbstverwaltungsrecht können ihre Aufgaben eigenständig organisieren und Entscheidungen unabhängig treffen, z. B. in der Raumordnung oder kommunalen Daseinsvorsorge (bei Gemeinden) oder in der Berufsregulierung (bei Kammern);  (iii) Staatliche Aufsicht: Trotz der Autonomie unterliegen Selbstverwaltungskörperschaften der staatlichen Rechtsaufsicht, die sicherstellt, dass sie ihre Aufgaben im Einklang mit geltenden Gesetzen und zum Wohl der Allgemeinheit erfüllen;  (iv) Demokratische Legitimation: Die Organe der Selbstverwaltung (z. B. [[Gemeinderäte]], [[Kammervorstände]]) werden meist durch demokratische Wahlen bestimmt, was die Unabhängigkeit der Entscheidungsfindung stärkt und Bürgernähe sichert"}, {"kategorie": "", "text": "Beispiele für das Selbstverwaltungsrecht:  (i) Gemeindeselbstverwaltung: Gemeinden können lokale Angelegenheiten wie Bauwesen, Infrastruktur und kommunale Abgaben selbstständig regeln und verwalten;  (ii) Berufsständische Selbstverwaltung: Kammern wie die [[Wirtschaftskammer]] oder die Ärztekammer regeln berufsständische Angelegenheiten, Prüfungen und Standards in ihrem Bereich;  (iii) Soziale Selbstverwaltung: [[Sozialversicherungsträger]], wie die [[Österreichische]] Gesundheitskasse, verwalten das Sozialversicherungssystem eigenverantwortlich und sichern Leistungen wie Gesundheits- und Pensionsversorgung."}]'::jsonb, ''),
  ('koeapaschoft', 'Köapaschoft', '', '', '', '', 'Körperschaft', '[{"kategorie": "allg.", "text": "\"rechtliche Organisation oder juristische Person, die aus einer Gruppe von Personen besteht und bestimmte Aufgaben und Ziele verfolgt\""}, {"kategorie": "", "text": "Eine Körperschaft hat eine eigenständige [[Rechtspersönlichkeit]], das heißt, sie kann eigenständig Verträge abschließen, Eigentum besitzen und vor Gericht klagen oder verklagt werden"}, {"kategorie": "", "text": "Körperschaften können im öffentlichen Recht oder im Privatrecht verankert sein"}, {"kategorie": "", "text": "Arten von Körperschaften in Österreich:  (i) [[Körperschaften]] des öffentlichen Rechts: Diese Körperschaften erfüllen öffentliche Aufgaben und unterliegen dem öffentlichen Recht. Sie sind oft hoheitlich tätig und handeln im Interesse des Gemeinwohls. Beispiele: [[Gemeinden]], [[Bundesländer]], der [[Bund]], [[Berufsvertretungen]] (z. B. Ärztekammer), [[Sozialversicherungsträger]] (z. B. [[Österreichische]] Gesundheitskasse);  (ii) [[Körperschaften]] des privaten Rechts: Diese Körperschaften entstehen durch privatrechtliche Verträge und dienen vorwiegend privaten Interessen. Sie unterliegen dem Zivilrecht. Beispiele: [[Vereine]], [[Genossenschaften]], Kapitalgesellschaften (z. B. Aktiengesellschaften und Gesellschaften mit beschränkter Haftung)"}, {"kategorie": "", "text": "Merkmale einer Körperschaft:  (i) [[Rechtspersönlichkeit]]: Körperschaften sind juristische Personen und damit Träger eigener Rechte und Pflichten;  (ii) Mitgliedschaft: Eine Körperschaft besteht aus Mitgliedern, die gemeinsam den Zweck der Körperschaft verfolgen. Die Mitgliedschaft kann freiwillig (z. B. in [[Vereinen]]) oder verpflichtend (z. B. in [[Kammern]]) sein;  (iii) Organe und Struktur: Körperschaften verfügen über eine festgelegte innere Struktur und Organe (z. B. [[Vorstand]], [[Aufsichtsrat]] oder [[Gemeinderat]]), die für Entscheidungen und Verwaltung zuständig sind"}, {"kategorie": "", "text": "In Österreich übernehmen [[Körperschaften]] des öffentlichen Rechts wichtige Verwaltungs- und Ordnungsaufgaben, wie die Vertretung bestimmter Berufsgruppen, die Verwaltung der Sozialversicherung oder die Bereitstellung kommunaler Dienstleistungen. Durch die Selbstverwaltung sind sie oft eigenverantwortlich tätig und entlasten den Staat, indem sie spezifische Aufgabenbereiche dezentral verwalten."}]'::jsonb, ''),
  ('schdiftung', 'Schdiftung', '', '', '', '', 'Stiftung', '[{"kategorie": "allg.", "text": "\"rechtliche Konstruktion, bei der ein Stifter Vermögen für einen bestimmten Zweck widmet und dieses Vermögen von einer eigenständigen [[juristischen]] Person, der Stiftung, verwaltet wird\""}, {"kategorie": "", "text": "Die Stiftung wird durch eine Stiftungsurkunde oder ein Stiftungsgeschäft gegründet, in dem der Stiftungszweck, die Art der Verwaltung und die Begünstigten festgelegt werden"}, {"kategorie": "", "text": "In Österreich gibt es verschiedene Arten von Stiftungen, die sich nach ihrem Zweck und ihrer rechtlichen Basis unterscheiden"}, {"kategorie": "", "text": "Merkmale einer Stiftung in Österreich:  (i) Eigene [[Rechtspersönlichkeit]]: Eine Stiftung ist eine juristische Person, die unabhängig vom Stifter und den Begünstigten besteht und eigene Rechte und Pflichten hat;  (ii) Stiftungszweck: Der Zweck der Stiftung ist in der Stiftungsurkunde festgelegt und kann sowohl gemeinnütziger (z. B. Förderung von Bildung oder Umweltschutz) als auch privater Natur sein (z. B. Vermögensverwaltung für eine Familie);  (iii) Unabhängigkeit des Vermögens: Das vom Stifter eingebrachte Vermögen geht in das Eigentum der Stiftung über und dient ausschließlich dem festgelegten Zweck, ohne dass der Stifter noch direkt darauf zugreifen kann;  (iv) Stiftungsverwaltung: Die Stiftung wird durch Organe verwaltet, die im Stiftungsgeschäft definiert sind, z. B. einen [[Stiftungsvorstand]]. Diese Organe sorgen für die ordnungsgemäße Verwaltung und Erfüllung des Stiftungszwecks"}, {"kategorie": "", "text": "Arten von Stiftungen in Österreich:  (i) [[Privatstiftung]]: Die österreichische Privatstiftung ist eine Sonderform, die häufig zur Verwaltung und Sicherung von Familienvermögen eingesetzt wird. Sie ist seit 1993 im Privatstiftungsgesetz geregelt und dient meist privaten Vermögenszwecken;  (ii) Gemeinnützige Stiftung: Diese Stiftungen verfolgen gemeinnützige, wohltätige oder kulturelle Zwecke und sind oft steuerlich begünstigt. Sie dienen dem Gemeinwohl, etwa durch Förderung von Bildung, Kunst, Wissenschaft oder Umweltschutz;  (iii) Kirchliche und öffentliche Stiftungen: Kirchliche Stiftungen dienen der Erfüllung religiöser Zwecke, während öffentliche Stiftungen spezielle staatliche Aufgaben wahrnehmen können (z. B. Kulturförderung)"}, {"kategorie": "", "text": "Funktionen und Vorteile einer Stiftung:  (i) Langfristige Vermögenssicherung: Stiftungen ermöglichen die langfristige Erhaltung und Verwaltung von Vermögen nach den Vorstellungen des Stifters;  (ii) Steuerliche Begünstigungen: Gemeinnützige Stiftungen können steuerliche Vorteile erhalten, wenn sie nachweislich dem Gemeinwohl dienen;  (iii) Schutz vor Erbteilung: Besonders Privatstiftungen schützen Familienvermögen vor einer Zersplitterung durch Erbteilungen und sichern die wirtschaftliche Unabhängigkeit von Familien."}]'::jsonb, ''),
  ('privatschdiftung', 'Privatschdiftung', '', '', '', '', 'Privatstiftung', '[{"kategorie": "allg.", "text": "\"eigenständige juristische Person, die von einem Stifter eingerichtet wird, um Vermögen für einen bestimmten, meist privaten Zweck zu verwalten und langfristig zu sichern\""}, {"kategorie": "", "text": "Die Privatstiftung ermöglicht es, Vermögen von der Person des Stifters zu trennen und es nach den in der Stiftungsurkunde festgelegten Richtlinien zu verwalten"}, {"kategorie": "", "text": "In Österreich wird die Privatstiftung durch das Privatstiftungsgesetz (PSG) geregelt, das 1993 eingeführt wurde, um eine flexible und rechtlich abgesicherte Form der Vermögensverwaltung zu schaffen"}, {"kategorie": "", "text": "Merkmale einer Privatstiftung:  (i) Eigenständige [[Rechtspersönlichkeit]]: Die Privatstiftung ist eine [[juristische]] Person, die unabhängig vom Stifter besteht und rechtlich eigenständig Vermögen verwaltet;  (ii) Vermögen und Zweckbindung: Das Vermögen, das der Stifter einbringt, gehört ab der Gründung ausschließlich der Stiftung und darf nur im Sinne des festgelegten Stiftungszwecks verwendet werden. Häufig ist der Zweck die Erhaltung und Verwaltung von Familienvermögen;  (iii) Stiftungsurkunde und Stiftungszweck: In der Stiftungsurkunde wird der Zweck der Privatstiftung festgelegt, etwa die Unterstützung von Familienmitgliedern oder die Finanzierung bestimmter Vorhaben. Dieser Zweck kann nicht willkürlich verändert werden, sondern ist langfristig festgelegt;  (iv) Organstruktur: Eine Privatstiftung hat in der Regel einen [[Vorstand]], der die laufende Verwaltung übernimmt. Weitere Organe können ein [[Aufsichtsrat]] (bei großen Stiftungen verpflichtend) und ein Stiftungsprüfer sein, der die Einhaltung der gesetzlichen Vorgaben überwacht;  (v) Begünstigte: Die Stiftungsurkunde legt fest, wer die Begünstigten sind (z. B. Familienmitglieder) und wie sie vom Vermögen profitieren, etwa in Form von Ausschüttungen oder finanzieller Unterstützung"}, {"kategorie": "", "text": "Ziele und Vorteile einer Privatstiftung:  (i) Vermögensschutz: Die Privatstiftung schützt das Stiftungsvermögen vor Zersplitterung durch Erbteilungen und ermöglicht eine generationsübergreifende Vermögensverwaltung;  (ii) Steuerliche Vorteile: Die Privatstiftung bietet unter bestimmten Bedingungen steuerliche Begünstigungen, insbesondere im Vergleich zu anderen Formen der Vermögensübertragung;  (iii) Flexible Vermögensgestaltung: Der Stifter kann die Regeln für die Verwaltung und Verwendung des Vermögens langfristig festlegen, was die Kontrolle über das Vermögen und dessen Verteilung sichert;  (iv) Anonymität und Diskretion: Die Begünstigten der Stiftung können im Hintergrund bleiben, da die Verwaltung über die Stiftung erfolgt und nicht direkt auf den Stifter oder die Familienmitglieder zurückzuführen ist"}, {"kategorie": "", "text": "Typische Anwendungsbereiche einer Privatstiftung:  (i) Familienvermögen: Verwaltung und Sicherung von Vermögen für kommende Generationen;  (ii) Unternehmensnachfolge: Sicherung und langfristige Steuerung eines Unternehmens, wenn der Stifter keine direkte Nachfolge einsetzen will;  (iii) Sozial- oder Bildungszwecke: Zwar seltener, doch Privatstiftungen können auch zur Förderung gemeinnütziger Zwecke eingesetzt werden, jedoch in Kombination mit privater Vermögensverwaltung"}, {"kategorie": "", "text": "Die österreichische Privatstiftung ist damit ein flexibles und effektives Instrument zur strukturierten Vermögensverwaltung und langfristigen Sicherung von Privat- und Familienvermögen."}]'::jsonb, ''),
  ('schdiftungsvuaschdaund', 'Schdiftungsvuaschdaund', '', '', '', '', 'Stiftungsvorstand', '[{"kategorie": "allg.", "text": "\"zentrales Leitungsorgan einer [[Stiftung]] in Österreich mit Verantwortung für die Verwaltung und Umsetzung des Stiftungszwecks gemäß den Vorgaben des Stifters und den rechtlichen Bestimmungen\""}, {"kategorie": "", "text": "In einer Stiftung ist der Stiftungsvorstand das entscheidende Gremium, das die Stiftung nach außen vertritt und sicherstellt, dass das Vermögen im Sinne des festgelegten Zwecks verwaltet wird"}, {"kategorie": "", "text": "Merkmale und Aufgaben des Stiftungsvorstands:  (i) Leitung und Verwaltung: Der Stiftungsvorstand führt die laufenden Geschäfte der Stiftung und ist für die ordnungsgemäße Verwaltung des Stiftungsvermögens verantwortlich;  (ii) Umsetzung des Stiftungszwecks: Der Vorstand sorgt dafür, dass die Stiftungstätigkeiten dem festgelegten Stiftungszweck entsprechen und die Mittel entsprechend eingesetzt werden;  (iii) Vertretung nach außen: Der Stiftungsvorstand repräsentiert die Stiftung nach außen und ist ermächtigt, Verträge abzuschließen und die Stiftung gegenüber Dritten zu vertreten;  (iv) Berichtspflicht: Der Stiftungsvorstand ist verpflichtet, regelmäßig über die Tätigkeiten und die finanzielle Situation der Stiftung Bericht zu erstatten, insbesondere gegenüber den Stiftungsaufsichtsbehörden und gegebenenfalls weiteren Kontrollorganen wie dem Stiftungsprüfer;  (v) Rechtliche Aufsicht: Der Vorstand unterliegt der gesetzlichen Aufsicht und muss sicherstellen, dass alle rechtlichen Vorschriften eingehalten werden. Dies wird insbesondere durch die Stiftungsaufsichtsbehörde und gegebenenfalls durch einen Stiftungsprüfer überprüft"}, {"kategorie": "", "text": "Der Stiftungsvorstand wird üblicherweise bei der Gründung der Stiftung bestimmt, und die Mitglieder werden meist vom Stifter oder dem [[Stiftungsrat]] berufen"}, {"kategorie": "", "text": "Der Stiftungsvorstand besteht in der Regel aus mehreren Personen, wobei das genaue Verfahren zur Bestellung und Amtsdauer in der [[Stiftungsurkunde]] festgelegt ist"}, {"kategorie": "", "text": "Die Mitglieder des Stiftungsvorstands sind dazu verpflichtet, ihre Aufgaben sorgfältig und verantwortungsbewusst wahrzunehmen. Sie haften für Schäden, die durch grobe Fahrlässigkeit oder Pflichtverletzung entstehen."}]'::jsonb, '')
